import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { jwtDecode } from 'jwt-decode';
import { User, Lock, LogIn, MessageCircle, Eye, EyeOff, Shield, BookOpen } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const LoginForm = ({ setToken }) => {
  const [formData, setFormData] = useState({
    dni: '',
    contraseña: ''
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();
  const [mostrarRegistro, setMostrarRegistro] = useState(false);
  const [checkingSetup, setCheckingSetup] = useState(true);

  // ✅ FUNCIÓN SIMPLIFICADA PARA REDIRIGIR SEGÚN ROL
  const redirigirSegunRol = (rol) => {
    switch (rol) {
      case 'ti':
        console.log('🔄 Redirigiendo a panel de TI');
        navigate('/dashboard');
        break;
      case 'formacion':
        console.log('🔄 Redirigiendo a panel de Formación');
        navigate('/dashboard');
        break;
      default:
        console.warn('⚠️ Rol no reconocido:', rol);
        setError('Rol de usuario no válido. Solo TI y Formación pueden acceder.');
        break;
    }
  };

  // ✅ Si ya hay token válido, redirigir al dashboard
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      try {
        const decoded = jwtDecode(token);
        console.log('🔍 Token existente encontrado, rol:', decoded.rol);
        redirigirSegunRol(decoded.rol);
      } catch (error) {
        console.log('❌ Token inválido o expirado, limpiando localStorage');
        localStorage.removeItem('token');
        localStorage.removeItem('rol');
      }
    }
  }, [navigate]);

  // ✅ VERIFICAR REGISTRO INICIAL AL CARGAR EL COMPONENTE
  useEffect(() => {
    verificarRegistroInicial();
  }, []);

  const verificarRegistroInicial = async () => {
    try {
      console.log('🔍 Verificando si necesita registro inicial...');

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch(`${API}/api/auth/verificar-registro-inicial`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      setMostrarRegistro(data.disponible);
      console.log('✅ Verificación completada:', data.disponible ? 'Mostrar registro' : 'Sistema ya configurado');

    } catch (error) {
      console.log('❌ Error verificando registro inicial:', error.message);

      if (error.name === 'AbortError') {
        console.log('⏰ Timeout - Servidor no responde');
      }

      // Fallback: mostrar registro solo si no hay token
      const token = localStorage.getItem('token');
      setMostrarRegistro(!token);
      console.log('💡 Usando fallback - Mostrar registro:', !token);
    } finally {
      setCheckingSetup(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === 'dni') {
      // Permitir solo números, máximo 8 dígitos
      const numericValue = value.replace(/\D/g, '').slice(0, 8);
      setFormData({
        ...formData,
        [name]: numericValue
      });
    } else {
      setFormData({
        ...formData,
        [name]: value
      });
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Validaciones básicas
    if (!formData.dni || !formData.contraseña) {
      setError('Por favor, completa todos los campos');
      setIsLoading(false);
      return;
    }

    if (!/^\d{6,8}$/.test(formData.dni)) {
      setError('El DNI debe tener entre 6 y 8 dígitos');
      setIsLoading(false);
      return;
    }

    try {
      console.log('🔐 Intentando login para DNI:', formData.dni);

      const res = await axios.post(`${API}/api/auth/login`, {
        dni: formData.dni.trim(),
        contraseña: formData.contraseña.trim()
      });

      if (!res.data.success || !res.data.token) {
        throw new Error('Respuesta inválida del servidor');
      }

      const token = res.data.token;
      const usuario = res.data.usuario;

      // Solo permitir acceso a roles válidos
      if (!['ti', 'formacion'].includes(usuario.rol)) {
        setError('Rol de usuario no autorizado. Solo TI y Formación pueden acceder.');
        setIsLoading(false);
        return;
      }

      // Guardar en localStorage
      localStorage.setItem('token', token);
      localStorage.setItem('rol', usuario.rol);

      // Actualizar estado global
      setToken(token);

      console.log('✅ Login exitoso:', usuario.nombre, usuario.apellido, `(${usuario.rol})`);

      // Redirigir según rol
      redirigirSegunRol(usuario.rol);

    } catch (err) {
      console.error('❌ Error en login:', err);

      let mensaje = 'Error al iniciar sesión';

      if (err.response?.status === 401) {
        mensaje = 'DNI o contraseña incorrectos';
      } else if (err.response?.status === 403) {
        mensaje = 'Usuario inactivo. Contacta al administrador.';
      } else if (err.response?.data?.message) {
        mensaje = err.response.data.message;
      } else if (!navigator.onLine) {
        mensaje = 'Sin conexión a internet';
      } else {
        mensaje = 'Error de conexión con el servidor';
      }

      setError(mensaje);
    } finally {
      setIsLoading(false);
    }
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  // Mostrar pantalla de carga mientras verifica setup
  if (checkingSetup) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-purple-600 to-indigo-700">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto"></div>
          <p className="mt-4 text-white">Verificando configuración del sistema...</p>
        </div>
      </div>
    );
  }

  // Mostrar setup inicial si es necesario
  if (mostrarRegistro) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-purple-600 to-indigo-700 px-4">
        <div className="max-w-md w-full">
          <div className="bg-white rounded-xl shadow-lg p-8">
            <div className="text-center mb-6">
              <div className="mx-auto h-16 w-16 bg-gradient-to-br from-blue-600 to-purple-600 rounded-full flex items-center justify-center shadow-lg mb-4">
                <Shield className="h-8 w-8 text-white" />
              </div>
              <h3 className="text-lg font-bold text-blue-800 mb-2">¡Configuración Inicial!</h3>
              <p className="text-sm text-blue-700 mb-1">Sistema sin usuarios configurados</p>
              <p className="text-xs text-blue-600">Crea el primer usuario administrador para comenzar</p>
            </div>
            <button
              type="button"
              onClick={() => navigate('/registro-inicial')}
              className="w-full px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-all duration-200 flex items-center justify-center space-x-2 shadow-md hover:shadow-lg"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
              <span>Configurar Sistema</span>
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex">

      {/* Sección Izquierda - Imagen */}
      <div className="hidden lg:flex lg:w-1/2 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-blue-600/20 via-purple-600/20 to-indigo-700/20 z-10"></div>
        <img
          src="/buhoti.png"
          alt="WSP Bot Partner"
          className="w-full h-full object-cover"
        />
      </div>


      {/* Sección Derecha - Formulario */}
      <div className="w-full lg:w-1/2 flex items-center justify-center bg-gray-50 px-6 py-12">
        <div className="max-w-md w-full space-y-8">
          {/* Header para pantallas móviles */}
          <div className="text-center lg:hidden">
            <div className="mx-auto h-16 w-16 bg-white rounded-full flex items-center justify-center shadow-lg mb-4">
              <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z" />
              </svg>
            </div>
            <h2 className="text-2xl font-bold text-gray-900 mb-2">
              TICHEK
            </h2>
            <p className="text-sm text-gray-600">
              Sistema de solicitudes
            </p>
          </div>

          {/* Header para pantallas grandes */}
          <div className="text-center hidden lg:block">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">
              TICHEK
            </h2>
            <p className="text-gray-600">
              Sistema de solicitudes
            </p>
          </div>

          {/* Formulario */}
          <div className="bg-white rounded-xl shadow-lg p-8">
            <form className="space-y-6" onSubmit={handleLogin}>
              <div>
                <label htmlFor="dni" className="block text-sm font-medium text-gray-700 mb-2">
                  DNI
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <User className="h-5 w-5 text-gray-400" />
                  </div>
                  <input
                    id="dni"
                    name="dni"
                    type="text"
                    autoComplete="username"
                    required
                    value={formData.dni}
                    onChange={handleChange}
                    className="block w-full pl-10 pr-3 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition duration-200 text-sm"
                    placeholder="12345678"
                    disabled={isLoading}
                    maxLength="8"
                  />
                </div>
                {formData.dni && !/^\d{6,8}$/.test(formData.dni) && (
                  <p className="text-amber-600 text-xs mt-1">El DNI debe tener entre 6 y 8 dígitos</p>
                )}
              </div>

              <div>
                <label htmlFor="contraseña" className="block text-sm font-medium text-gray-700 mb-2">
                  Contraseña
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Lock className="h-5 w-5 text-gray-400" />
                  </div>
                  <input
                    id="contraseña"
                    name="contraseña"
                    type={showPassword ? "text" : "password"}
                    autoComplete="current-password"
                    required
                    value={formData.contraseña}
                    onChange={handleChange}
                    className="block w-full pl-10 pr-12 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition duration-200 text-sm"
                    placeholder="Tu contraseña"
                    disabled={isLoading}
                  />
                  <button
                    type="button"
                    className="absolute inset-y-0 right-0 pr-3 flex items-center"
                    onClick={togglePasswordVisibility}
                    disabled={isLoading}
                  >
                    {showPassword ? (
                      <EyeOff className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                    ) : (
                      <Eye className="h-5 w-5 text-gray-400 hover:text-gray-600" />
                    )}
                  </button>
                </div>
              </div>

              {/* Error */}
              {error && (
                <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-start space-x-2">
                  <svg className="w-5 h-5 text-red-500 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                  </svg>
                  <div>
                    <p className="text-sm font-medium">Error de autenticación</p>
                    <p className="text-sm">{error}</p>
                  </div>
                </div>
              )}

              <div>
                <button
                  type="submit"
                  disabled={isLoading || !formData.dni || !formData.contraseña}
                  className="group relative w-full flex justify-center py-3 px-4 border border-transparent text-sm font-medium rounded-lg text-white bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition duration-200 shadow-lg hover:shadow-xl"
                >
                  {isLoading ? (
                    <div className="flex items-center">
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      Iniciando sesión...
                    </div>
                  ) : (
                    <div className="flex items-center">
                      <LogIn className="h-4 w-4 mr-2" />
                      Iniciar Sesión
                    </div>
                  )}
                </button>
              </div>
            </form>

            {/* Enlace a solicitudes públicas */}
            <div className="mt-6 text-center">
              <button
                onClick={() => navigate('/solicitudes-publicas')}
                className="text-blue-600 hover:text-blue-800 font-medium text-sm hover:underline transition-colors duration-200"
              >
                📊 Ver Estado de Solicitudes (Público)
              </button>
            </div>

            {/* Footer */}
            <div className="mt-6 pt-6 border-t border-gray-100">
              <p className="text-center text-xs text-gray-500">
                Sistema TICHECK · v3.0 · Desarrollado por JESB
              </p>
            </div>
          </div>

          {/* Footer para móviles */}
          <div className="text-center lg:hidden">
            <div className="flex items-center justify-center space-x-6 text-sm text-gray-500">
              <div className="flex items-center space-x-1">
                <svg className="w-4 h-4 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                </svg>
                <span>Seguro</span>
              </div>
              <div className="flex items-center space-x-1">
                <svg className="w-4 h-4 text-blue-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                </svg>
                <span>Soporte</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginForm;