import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const EditarUsuario = ({ usuario, onClose, onUsuarioActualizado, mostrarNotificacion }) => {
    const [form, setForm] = useState({
        dni: '',
        nombre: '',
        apellido: '',
        rol: 'formacion',
        activo: true
    });

    const [errores, setErrores] = useState({});
    const [enviando, setEnviando] = useState(false);
    const [mostrarCambiarClave, setMostrarCambiarClave] = useState(false);
    const [nuevaClave, setNuevaClave] = useState('');
    const [confirmarNuevaClave, setConfirmarNuevaClave] = useState('');

    // Cargar datos del usuario al abrir el modal
    useEffect(() => {
        if (usuario) {
            setForm({
                dni: usuario.dni || '',
                nombre: usuario.nombre || '',
                apellido: usuario.apellido || '',
                rol: usuario.rol || 'formacion',
                activo: usuario.activo !== undefined ? usuario.activo : true
            });
        }
    }, [usuario]);

    // Validaciones en tiempo real
    useEffect(() => {
        const validar = () => {
            const nuevosErrores = {};

            // DNI formato
            if (form.dni && !/^\d{8}$/.test(form.dni)) {
                nuevosErrores.dni = 'DNI debe tener exactamente 8 dígitos';
            }

            // Nombre
            if (form.nombre && form.nombre.trim().length < 2) {
                nuevosErrores.nombre = 'El nombre debe tener al menos 2 caracteres';
            }

            // Apellido
            if (form.apellido && form.apellido.trim().length < 2) {
                nuevosErrores.apellido = 'El apellido debe tener al menos 2 caracteres';
            }

            // Validar nueva contraseña si se está cambiando
            if (mostrarCambiarClave) {
                if (nuevaClave && nuevaClave.length < 6) {
                    nuevosErrores.nuevaClave = 'La contraseña debe tener al menos 6 caracteres';
                }

                if (nuevaClave !== confirmarNuevaClave) {
                    nuevosErrores.confirmarNuevaClave = 'Las contraseñas no coinciden';
                }
            }

            setErrores(nuevosErrores);
        };

        const timeout = setTimeout(validar, 300);
        return () => clearTimeout(timeout);
    }, [form, mostrarCambiarClave, nuevaClave, confirmarNuevaClave]);

    // Manejar cambios en el formulario
    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setForm(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    // Verificar si el formulario es válido
    const formularioValido = () => {
        const camposObligatorios = ['dni', 'nombre', 'apellido'];
        const todosLlenos = camposObligatorios.every(campo => form[campo]?.trim());
        const sinErrores = Object.keys(errores).length === 0;

        // Si está cambiando contraseña, verificar que esté completa
        const claveValida = !mostrarCambiarClave ||
            (nuevaClave && confirmarNuevaClave && !errores.nuevaClave && !errores.confirmarNuevaClave);

        return todosLlenos && sinErrores && claveValida;
    };

    // Actualizar usuario
    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!formularioValido()) {
            mostrarNotificacion('Por favor, completa todos los campos correctamente', 'error');
            return;
        }

        setEnviando(true);

        try {
            const datosUsuario = {
                id: usuario.id,
                nombre: form.nombre.trim(),
                apellido: form.apellido.trim(),
                rol: form.rol,
                activo: form.activo
            };

            // Agregar nueva contraseña si se está cambiando
            if (mostrarCambiarClave && nuevaClave) {
                datosUsuario.contraseña = nuevaClave;
            }

            await axios.put(`${API}/api/sistemas/usuarios/${usuario.id}`, datosUsuario, {
                headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
            });

            mostrarNotificacion(`Usuario ${form.nombre} ${form.apellido} actualizado exitosamente`, 'success');

            // Recargar usuarios
            if (onUsuarioActualizado) await onUsuarioActualizado();
            onClose();

        } catch (error) {
            console.error('Error al actualizar usuario:', error);
            const mensaje = error.response?.data?.message || 'Error al actualizar usuario';
            mostrarNotificacion(mensaje, 'error');
        } finally {
            setEnviando(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[95vh] overflow-y-auto">
                {/* Header */}
                <div className="sticky top-0 bg-white p-6 border-b border-gray-200 rounded-t-2xl z-10">
                    <div className="flex items-center justify-between">
                        <h2 className="text-xl font-bold text-gray-800">
                            ✏️ Editar Usuario
                        </h2>
                        <button
                            onClick={onClose}
                            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                        >
                            <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>
                    <p className="text-gray-600 mt-1">
                        Editando: {usuario?.nombre} {usuario?.apellido}
                    </p>
                </div>

                {/* Contenido */}
                <div className="p-6">
                    <form onSubmit={handleSubmit} className="space-y-5">
                        {/* DNI (solo lectura) */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                DNI
                            </label>
                            <input
                                type="text"
                                name="dni"
                                value={form.dni}
                                readOnly
                                className="w-full px-3 py-3 border border-gray-300 rounded-lg bg-gray-100 cursor-not-allowed"
                            />
                        </div>

                        {/* Nombre y Apellido */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Nombre *
                                </label>
                                <input
                                    type="text"
                                    name="nombre"
                                    value={form.nombre}
                                    onChange={handleChange}
                                    className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.nombre ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                        }`}
                                    placeholder="Ej: Juan"
                                    required
                                />
                                {errores.nombre && (
                                    <p className="text-red-500 text-xs mt-1">{errores.nombre}</p>
                                )}
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Apellido *
                                </label>
                                <input
                                    type="text"
                                    name="apellido"
                                    value={form.apellido}
                                    onChange={handleChange}
                                    className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.apellido ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                        }`}
                                    placeholder="Ej: Pérez"
                                    required
                                />
                                {errores.apellido && (
                                    <p className="text-red-500 text-xs mt-1">{errores.apellido}</p>
                                )}
                            </div>
                        </div>

                        {/* Rol */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Rol *
                            </label>
                            <select
                                name="rol"
                                value={form.rol}
                                onChange={handleChange}
                                className="w-full px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent transition-all duration-200"
                                required
                            >
                                <option value="formacion">🎓 Formación</option>
                                <option value="ti">💻 TI (Sistemas)</option>
                            </select>
                        </div>

                        {/* Estado */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Estado
                            </label>
                            <select
                                name="activo"
                                value={form.activo}
                                onChange={(e) => setForm({ ...form, activo: e.target.value === 'true' })}
                                className="w-full px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent transition-all duration-200"
                            >
                                <option value={true}>✅ Activo</option>
                                <option value={false}>❌ Inactivo</option>
                            </select>
                        </div>

                        {/* Cambiar contraseña */}
                        <div className="pt-4 border-t border-gray-200">
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="text-lg font-semibold text-gray-800">
                                    🔐 Cambiar Contraseña
                                </h3>
                                <button
                                    type="button"
                                    onClick={() => {
                                        setMostrarCambiarClave(!mostrarCambiarClave);
                                        if (mostrarCambiarClave) {
                                            setNuevaClave('');
                                            setConfirmarNuevaClave('');
                                        }
                                    }}
                                    className={`px-4 py-2 rounded-lg transition-colors ${mostrarCambiarClave
                                            ? 'bg-red-100 text-red-700 hover:bg-red-200'
                                            : 'bg-blue-100 text-blue-700 hover:bg-blue-200'
                                        }`}
                                >
                                    {mostrarCambiarClave ? 'Cancelar' : 'Cambiar Contraseña'}
                                </button>
                            </div>

                            {mostrarCambiarClave && (
                                <div className="space-y-4 p-4 bg-gray-50 rounded-lg border border-gray-200">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-2">
                                            Nueva Contraseña *
                                        </label>
                                        <input
                                            type="password"
                                            value={nuevaClave}
                                            onChange={(e) => setNuevaClave(e.target.value)}
                                            className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.nuevaClave ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                                }`}
                                            placeholder="Mínimo 6 caracteres"
                                        />
                                        {errores.nuevaClave && (
                                            <p className="text-red-500 text-xs mt-1">{errores.nuevaClave}</p>
                                        )}
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-2">
                                            Confirmar Nueva Contraseña *
                                        </label>
                                        <input
                                            type="password"
                                            value={confirmarNuevaClave}
                                            onChange={(e) => setConfirmarNuevaClave(e.target.value)}
                                            className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.confirmarNuevaClave ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                                }`}
                                            placeholder="Repetir nueva contraseña"
                                        />
                                        {errores.confirmarNuevaClave && (
                                            <p className="text-red-500 text-xs mt-1">{errores.confirmarNuevaClave}</p>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Estado del formulario */}
                        <div className="pt-4 border-t border-gray-200">
                            {formularioValido() ? (
                                <div className="flex items-center text-green-600 text-sm font-medium mb-4">
                                    <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                                    </svg>
                                    ✅ Listo para actualizar usuario
                                </div>
                            ) : (
                                <div className="flex items-center text-orange-600 text-sm font-medium mb-4">
                                    <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                                    </svg>
                                    ⚠️ Completa los campos requeridos
                                </div>
                            )}
                        </div>
                    </form>
                </div>

                {/* Footer */}
                <div className="sticky bottom-0 bg-white p-6 border-t border-gray-200 rounded-b-2xl">
                    <div className="flex flex-col sm:flex-row justify-end space-y-3 sm:space-y-0 sm:space-x-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="w-full sm:w-auto px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors font-medium"
                            disabled={enviando}
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            onClick={handleSubmit}
                            disabled={!formularioValido() || enviando}
                            className={`w-full sm:w-auto px-6 py-3 rounded-lg font-medium transition-all duration-200 flex items-center justify-center space-x-2 ${formularioValido() && !enviando
                                    ? 'bg-blue-600 text-white hover:bg-blue-700 hover:shadow-lg'
                                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                }`}
                        >
                            {enviando ? (
                                <>
                                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                                    <span>Actualizando...</span>
                                </>
                            ) : (
                                <>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
                                    </svg>
                                    <span>Actualizar Usuario</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EditarUsuario;