import React from 'react';
import Notificacion from './Notificacion';

const ContenedorNotificaciones = ({ notificaciones, onCerrar }) => {
    return (
        <div className="fixed top-8 right-4 z-50 flex flex-col items-end gap-4 pointer-events-none">
            {notificaciones.map((notificacion) => (
                <div key={notificacion.id} className="pointer-events-auto">
                    <Notificacion
                        mensaje={notificacion.mensaje}
                        tipo={notificacion.tipo}
                        duracion={notificacion.duracion}
                        onClose={() => onCerrar(notificacion.id)}
                    />
                </div>
            ))}
        </div>
    );
};

export default ContenedorNotificaciones;