import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const HistorialEliminaciones = ({ token, mostrarNotificacion }) => {
    const [eliminaciones, setEliminaciones] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filtros, setFiltros] = useState({
        desde: '',
        hasta: '',
        usuario_eliminado: '',
        responsable: '',
        metodo: ''
    });
    const [exportando, setExportando] = useState(false);
    const [pagination, setPagination] = useState({
        currentPage: 1,
        totalPages: 1,
        totalItems: 0,
        itemsPerPage: 20
    });

    useEffect(() => {
        cargarEliminaciones();
    }, [filtros, pagination.currentPage]);

    const cargarEliminaciones = async () => {
        try {
            setLoading(true);
            const params = new URLSearchParams({
                page: pagination.currentPage,
                limit: pagination.itemsPerPage,
                ...filtros
            });

            const response = await axios.get(`${API}/api/ti/eliminaciones?${params}`, {
                headers: { Authorization: `Bearer ${token}` }
            });

            if (response.data.success) {
                setEliminaciones(response.data.eliminaciones);
                setPagination(response.data.pagination);
            }
        } catch (error) {
            console.error('Error al cargar eliminaciones:', error);
            mostrarNotificacion('Error al cargar el historial de eliminaciones', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleFiltroChange = (e) => {
        const { name, value } = e.target;
        setFiltros(prev => ({
            ...prev,
            [name]: value
        }));
        setPagination(prev => ({ ...prev, currentPage: 1 }));
    };

    const limpiarFiltros = () => {
        setFiltros({
            desde: '',
            hasta: '',
            usuario_eliminado: '',
            responsable: '',
            metodo: ''
        });
        setPagination(prev => ({ ...prev, currentPage: 1 }));
    };

    const exportarExcel = async () => {
        try {
            setExportando(true);
            const params = new URLSearchParams(filtros);
            
            const response = await axios.get(`${API}/api/ti/eliminaciones/export?${params}`, {
                headers: { Authorization: `Bearer ${token}` },
                responseType: 'blob'
            });

            // Crear enlace de descarga
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            
            // Generar nombre del archivo con fecha
            const fechaActual = new Date().toISOString().split('T')[0];
            link.setAttribute('download', `historial_eliminaciones_${fechaActual}.xlsx`);
            
            document.body.appendChild(link);
            link.click();
            link.remove();
            window.URL.revokeObjectURL(url);

            mostrarNotificacion('Archivo Excel exportado exitosamente', 'success');
        } catch (error) {
            console.error('Error al exportar:', error);
            mostrarNotificacion('Error al exportar el archivo Excel', 'error');
        } finally {
            setExportando(false);
        }
    };

    const formatearFecha = (fecha) => {
        if (!fecha) return '-';
        return new Date(fecha).toLocaleString('es-PE', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: false
        });
    };

    const cambiarPagina = (nuevaPagina) => {
        setPagination(prev => ({ ...prev, currentPage: nuevaPagina }));
    };

    if (loading && eliminaciones.length === 0) {
        return (
            <div className="bg-white rounded-lg shadow-md p-6">
                <div className="flex justify-center items-center py-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-4 border-blue-500 border-t-transparent"></div>
                    <span className="ml-3 text-gray-600">Cargando historial...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-lg shadow-md p-6">
            <div className="mb-6">
                <div className="flex justify-between items-start mb-4">
                    <div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">
                            📋 Historial de Eliminaciones
                        </h2>
                        <p className="text-gray-600">
                            Registro completo de eliminaciones de usuarios realizadas por TI
                        </p>
                    </div>
                    <button
                        onClick={exportarExcel}
                        disabled={exportando}
                        className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center space-x-2 disabled:opacity-50"
                    >
                        {exportando ? (
                            <>
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                                <span>Exportando...</span>
                            </>
                        ) : (
                            <>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                                </svg>
                                <span>Exportar Excel</span>
                            </>
                        )}
                    </button>
                </div>

                {/* Filtros */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 mb-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Desde
                        </label>
                        <input
                            type="date"
                            name="desde"
                            value={filtros.desde}
                            onChange={handleFiltroChange}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Hasta
                        </label>
                        <input
                            type="date"
                            name="hasta"
                            value={filtros.hasta}
                            onChange={handleFiltroChange}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Usuario Eliminado
                        </label>
                        <input
                            type="text"
                            name="usuario_eliminado"
                            value={filtros.usuario_eliminado}
                            onChange={handleFiltroChange}
                            placeholder="DNI..."
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Responsable
                        </label>
                        <input
                            type="text"
                            name="responsable"
                            value={filtros.responsable}
                            onChange={handleFiltroChange}
                            placeholder="Nombre..."
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            Método
                        </label>
                        <select
                            name="metodo"
                            value={filtros.metodo}
                            onChange={handleFiltroChange}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                        >
                            <option value="">Todos</option>
                            <option value="GUI + validación manual">GUI + validación manual</option>
                            <option value="Comando PowerShell">Comando PowerShell</option>
                            <option value="Active Directory">Active Directory</option>
                            <option value="Eliminación física">Eliminación física</option>
                            <option value="Desactivación temporal">Desactivación temporal</option>
                        </select>
                    </div>
                </div>

                <div className="flex justify-between items-center">
                    <button
                        onClick={limpiarFiltros}
                        className="px-4 py-2 text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors text-sm"
                    >
                        Limpiar Filtros
                    </button>
                    <button
                        onClick={cargarEliminaciones}
                        disabled={loading}
                        className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm disabled:opacity-50"
                    >
                        {loading ? 'Buscando...' : 'Buscar'}
                    </button>
                </div>
            </div>

            {/* Tabla */}
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Fecha
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Usuario Eliminado
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Equipo
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Responsable
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Método
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Observaciones
                            </th>
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {eliminaciones.length === 0 ? (
                            <tr>
                                <td colSpan="6" className="px-6 py-4 text-center text-gray-500">
                                    No se encontraron registros
                                </td>
                            </tr>
                        ) : (
                            eliminaciones.map((eliminacion) => (
                                <tr key={eliminacion.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {formatearFecha(eliminacion.fecha_eliminacion)}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                        {eliminacion.usuario_eliminado}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {eliminacion.equipo_hostname}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {eliminacion.responsable_nombre}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-blue-100 text-blue-800">
                                            {eliminacion.metodo_aplicado}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-sm text-gray-900 max-w-xs">
                                        <div className="truncate" title={eliminacion.observaciones}>
                                            {eliminacion.observaciones || '-'}
                                        </div>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Paginación */}
            {pagination.totalPages > 1 && (
                <div className="mt-6 flex justify-between items-center">
                    <div className="text-sm text-gray-700">
                        Mostrando {((pagination.currentPage - 1) * pagination.itemsPerPage) + 1} - {Math.min(pagination.currentPage * pagination.itemsPerPage, pagination.totalItems)} de {pagination.totalItems} registros
                    </div>
                    <div className="flex space-x-2">
                        <button
                            onClick={() => cambiarPagina(pagination.currentPage - 1)}
                            disabled={pagination.currentPage === 1}
                            className="px-3 py-1 border border-gray-300 rounded text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                        >
                            Anterior
                        </button>
                        <span className="px-3 py-1 text-sm text-gray-700">
                            Página {pagination.currentPage} de {pagination.totalPages}
                        </span>
                        <button
                            onClick={() => cambiarPagina(pagination.currentPage + 1)}
                            disabled={pagination.currentPage === pagination.totalPages}
                            className="px-3 py-1 border border-gray-300 rounded text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
                        >
                            Siguiente
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default HistorialEliminaciones;
