import React, { useState, useEffect } from 'react';
import { User, Plus, List, LogOut } from 'lucide-react';
import ContenedorNotificaciones from '../common/ContenedorNotificaciones';
import useNotificacion from '../../hooks/useNotificacion';


const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';


const PanelFormacion = () => {
  const [usuario, setUsuario] = useState(null);
  const [vistaActual, setVistaActual] = useState('inicio');
  const [modalHistorial, setModalHistorial] = useState(null);
  const [historial, setHistorial] = useState([]);
  const [cargandoHistorial, setCargandoHistorial] = useState(false);
  const noti = useNotificacion();

  useEffect(() => {
    // Obtener datos del usuario desde el backend
    const token = localStorage.getItem('token');
    if (token) {
      fetch(`${API}/api/usuarios/perfil`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      })
        .then(res => res.json())
        .then(data => {
          if (data && data.usuario) {
            setUsuario(data.usuario);
          }
        })
        .catch(() => setUsuario(null));
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('usuario');
    window.location.href = '/login';
  };

  const menuItems = [
    { id: 'inicio', label: 'Inicio', icon: User },
    { id: 'crear', label: 'Crear Solicitud', icon: Plus },
    { id: 'mis-solicitudes', label: 'Mis Solicitudes', icon: List }
  ];

  const verHistorial = async (id) => {
    setCargandoHistorial(true);
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API}/api/formacion/solicitudes/${id}/historial`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json();
      setHistorial(data.historial || []);
      setModalHistorial(true);
    } catch (error) {
      alert('Error al cargar historial');
    } finally {
      setCargandoHistorial(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <ContenedorNotificaciones notificaciones={noti.notificaciones} onCerrar={noti.cerrarNotificacion} />
      {/* Header */}
      <header className="bg-blue-600 text-white shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-4">
            <div className="flex items-center space-x-4">
              <div className="bg-blue-700 p-2 rounded-lg">
                <User className="h-6 w-6" />
              </div>
              <div>
                <h1 className="text-xl font-semibold">TICHECK</h1>
                <p className="text-blue-200 text-sm">
                  {usuario ? `${usuario.nombre} ${usuario.apellido}` : 'Cargando...'}
                </p>
              </div>
            </div>
            <button
              onClick={handleLogout}
              className="flex items-center space-x-2 bg-blue-700 hover:bg-blue-800 px-4 py-2 rounded-lg transition-colors"
            >
              <LogOut className="h-4 w-4" />
              <span>Cerrar Sesión</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-full mx-auto px-2 sm:px-8 lg:px-16 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
          {/* Sidebar */}
          <div className="lg:col-span-1 min-w-[220px]">
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-lg font-semibold text-gray-800 mb-4">Menú</h2>
              <nav className="space-y-2">
                {menuItems.map((item) => {
                  const Icon = item.icon;
                  return (
                    <button
                      key={item.id}
                      onClick={() => setVistaActual(item.id)}
                      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg text-left transition-colors ${vistaActual === item.id
                        ? 'bg-blue-50 text-blue-700 border-l-4 border-blue-500'
                        : 'text-gray-600 hover:bg-gray-50'
                        }`}
                    >
                      <Icon className="h-5 w-5" />
                      <span>{item.label}</span>
                    </button>
                  );
                })}
              </nav>
            </div>
          </div>

          {/* Contenido principal */}
          <div className="lg:col-span-4">
            <div className="bg-white rounded-lg shadow-md p-8">
              {vistaActual === 'inicio' && (
                <div>
                  <h2 className="text-2xl font-bold text-gray-800 mb-6">
                    Bienvenido al Sistema de Solicitudes
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="bg-gradient-to-r from-blue-500 to-blue-600 p-6 rounded-lg text-white">
                      <h3 className="text-lg font-semibold mb-2">Crear Nueva Solicitud</h3>
                      <p className="text-blue-100 mb-4">
                        Registra una nueva solicitud de instalación para un asesor
                      </p>
                      <button
                        onClick={() => setVistaActual('crear')}
                        className="bg-white text-blue-600 px-4 py-2 rounded-lg font-medium hover:bg-blue-50 transition-colors"
                      >
                        Crear Solicitud
                      </button>
                    </div>

                    <div className="bg-gradient-to-r from-green-500 to-green-600 p-6 rounded-lg text-white">
                      <h3 className="text-lg font-semibold mb-2">Mis Solicitudes</h3>
                      <p className="text-green-100 mb-4">
                        Revisa el estado de todas tus solicitudes enviadas
                      </p>
                      <button
                        onClick={() => setVistaActual('mis-solicitudes')}
                        className="bg-white text-green-600 px-4 py-2 rounded-lg font-medium hover:bg-green-50 transition-colors"
                      >
                        Ver Solicitudes
                      </button>
                    </div>
                  </div>

                  <div className="mt-8 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                    <h4 className="font-semibold text-yellow-800 mb-2">Información Importante</h4>
                    <ul className="text-yellow-700 text-sm space-y-1">
                      <li>• Asegúrate de completar todos los campos obligatorios</li>
                      <li>• El DNI del asesor debe tener exactamente 8 dígitos</li>
                      <li>• Verifica que el código AnyDesk sea correcto</li>
                      <li>• Las solicitudes son revisadas por el equipo de TI</li>
                    </ul>
                  </div>
                </div>
              )}

              {vistaActual === 'crear' && (
                <CrearSolicitud onSuccess={() => setVistaActual('mis-solicitudes')} noti={noti} />
              )}

              {vistaActual === 'mis-solicitudes' && (
                <MisSolicitudes verHistorial={verHistorial} noti={noti} />
              )}
            </div>
          </div>
        </div>
      </div>

      {modalHistorial && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold text-gray-800">Historial de Solicitud</h2>
                <button
                  onClick={() => setModalHistorial(false)}
                  className="p-2 hover:bg-gray-100 rounded-lg"
                >
                  <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              {cargandoHistorial ? (
                <div className="flex justify-center py-8">
                  <div className="animate-spin rounded-full h-10 w-10 border-4 border-blue-500 border-t-transparent"></div>
                </div>
              ) : historial.length === 0 ? (
                <div className="text-center text-gray-500">No hay historial para esta solicitud.</div>
              ) : (
                <ul className="divide-y divide-gray-200">
                  {historial.map((h) => (
                    <li key={h.id} className="py-4">
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="font-medium text-gray-800">{h.accion} ({h.estado_nuevo})</p>
                          <p className="text-sm text-gray-600">Por: {h.usuario_nombre || 'Sistema'} ({h.rol || '-'})</p>
                          <p className="text-xs text-gray-400">{h.fecha ? new Date(h.fecha).toLocaleString('es-PE', { timeZone: 'America/Lima', hour12: false }) : ''}</p>
                        </div>
                        {h.observaciones && (
                          <div className="ml-4 text-sm text-gray-700 max-w-xs break-words">{h.observaciones}</div>
                        )}
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Componente CrearSolicitud
const CrearSolicitud = ({ onSuccess, noti }) => {
  const [formData, setFormData] = useState({
    dni_asesor: '',
    nombre_asesor: '',
    campaña: '',
    anydesk: '',
    correo_usuario: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API}/api/formacion/solicitudes`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        setFormData({
          dni_asesor: '',
          nombre_asesor: '',
          campaña: '',
          anydesk: '',
          correo_usuario: ''
        });
        noti.exito('Solicitud creada exitosamente');
        onSuccess();
      } else {
        const errorData = await response.json();
        setError(errorData.message || 'Error al crear la solicitud');
      }
    } catch (error) {
      setError('Error de conexión');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">Crear Nueva Solicitud</h2>

      {error && (
        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            DNI del Asesor
          </label>
          <input
            type="text"
            name="dni_asesor"
            value={formData.dni_asesor}
            onChange={handleInputChange}
            maxLength="8"
            pattern="[0-9]{6,8}"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            placeholder="12345678"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Nombre y Apellido del Asesor
          </label>
          <div className="flex gap-2">
            <input
              type="text"
              name="nombre_asesor_nombre"
              value={formData.nombre_asesor_nombre || ''}
              onChange={e => {
                const upperValue = e.target.value.toUpperCase();
                setFormData(prev => ({
                  ...prev,
                  nombre_asesor_nombre: upperValue.replace(/[^A-ZÁÉÍÓÚÜÑ\s]/gi, ''),
                  nombre_asesor: (upperValue + ' ' + (prev.nombre_asesor_apellido || '')).trim()
                }));
              }}
              required
              className="w-1/2 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              placeholder="Nombre(s)"
              autoComplete="off"
              inputMode="text"
            />
            <input
              type="text"
              name="nombre_asesor_apellido"
              value={formData.nombre_asesor_apellido || ''}
              onChange={e => {
                const upperValue = e.target.value.toUpperCase();
                setFormData(prev => ({
                  ...prev,
                  nombre_asesor_apellido: upperValue.replace(/[^A-ZÁÉÍÓÚÜÑ\s]/gi, ''),
                  nombre_asesor: ((prev.nombre_asesor_nombre || '') + ' ' + upperValue).trim()
                }));
              }}
              required
              className="w-1/2 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              placeholder="Apellido(s)"
              autoComplete="off"
              inputMode="text"
            />
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Campaña
          </label>
          <select
            name="campaña"
            value={formData.campaña}
            onChange={handleInputChange}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">Selecciona una campaña</option>
            <option value="PORTABILIDAD">PORTABILIDAD</option>
            <option value="RENOVACION">RENOVACION</option>
            <option value="MIGRACIONES">MIGRACIONES</option>
            <option value="PREVENTIVA FIJA">PREVENTIVA FIJA</option>
            <option value="UPGRADE FIJA">UPGRADE FIJA</option>
            <option value="UPGRADE MOVIL">UPGRADE MÓVIL</option>
            <option value="CONVERGENTE">CONVERGENTE</option>
            <option value="OLAS">OLAS</option>
            <option value="DOWNGRADE">DOWNGRADE</option>
            <option value="RETENCIONES WHATSAPP">RETENCIONES WHATSAPP</option>
            <option value="CONTACTADOS">CONTACTADOS</option>
            <option value="PREVENTIVA MOVIL">PREVENTIVA MOVIL</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Correo del Usuario
          </label>
          <input
            type="email"
            name="correo_usuario"
            value={formData.correo_usuario}
            onChange={handleInputChange}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            placeholder="usuario@partner.pe"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Código AnyDesk
          </label>
          <input
            type="text"
            name="anydesk"
            value={formData.anydesk}
            onChange={handleInputChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            placeholder="123456789"
          />
        </div>

        <div className="flex justify-end space-x-4">
          <button
            type="button"
            onClick={() => setFormData({
              dni_asesor: '',
              nombre_asesor: '',
              campaña: '',
              anydesk: '',
              correo_usuario: ''
            })}
            className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
          >
            Limpiar
          </button>
          <button
            type="submit"
            disabled={loading}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
          >
            {loading ? 'Creando...' : 'Crear Solicitud'}
          </button>
        </div>
      </form>
    </div>
  );
};

// Componente MisSolicitudes
const MisSolicitudes = ({ verHistorial, noti }) => {
  const [solicitudes, setSolicitudes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [modalDetalles, setModalDetalles] = useState(null);

  useEffect(() => {
    fetchSolicitudes(false); // No notificación al montar
  }, []);

  // Cambia: recibe showNoti para controlar si mostrar notificación
  const fetchSolicitudes = async (showNoti = false) => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`${API}/api/formacion/mis-solicitudes`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      if (response.ok) {
        const data = await response.json();
        setSolicitudes(data.solicitudes);
        if (noti && showNoti) noti.info('Lista actualizada');
      } else {
        setError('Error al cargar las solicitudes');
      }
    } catch (error) {
      setError('Error de conexión');
    } finally {
      setLoading(false);
    }
  };

  const getEstadoBadge = (estado) => {
    const badges = {
      'pendiente': 'bg-yellow-100 text-yellow-800',
      'aprobada': 'bg-green-100 text-green-800',
      'rechazada': 'bg-red-100 text-red-800'
    };
    return badges[estado] || 'bg-gray-100 text-gray-800';
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-8">
        <div className="text-gray-600">Cargando solicitudes...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
        {error}
      </div>
    );
  }

  // Ordenar: pendientes primero, luego aprobadas y rechazadas por fecha
  const solicitudesOrdenadas = [...solicitudes].sort((a, b) => {
    if (a.estado === 'pendiente' && b.estado !== 'pendiente') return -1;
    if (a.estado !== 'pendiente' && b.estado === 'pendiente') return 1;
    // Si ambos no son pendientes, ordenar por fecha_creacion descendente
    const fechaA = new Date(a.fecha_creacion);
    const fechaB = new Date(b.fecha_creacion);
    return fechaB - fechaA;
  });

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold text-gray-800">Mis Solicitudes</h2>
        <button
          onClick={() => fetchSolicitudes(true)}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow"
        >
          <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582M20 20v-5h-.581M5 19a9 9 0 1010-10" /></svg>
          Actualizar
        </button>
      </div>
      {solicitudesOrdenadas.length === 0 ? (
        <div className="text-center py-8 text-gray-500">
          No tienes solicitudes registradas
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Asesor
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Campaña
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Estado
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Revisando
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Fecha
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Observaciones
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {solicitudesOrdenadas.map((solicitud) => (
                <tr key={solicitud.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-gray-900">
                        {solicitud.nombre_asesor}
                      </div>
                      <div className="text-sm text-gray-500">
                        DNI: {solicitud.dni_asesor}
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {solicitud.campaña}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getEstadoBadge(solicitud.estado)}`}>
                      {solicitud.estado.toUpperCase()}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {solicitud.estado === 'pendiente' && solicitud.revisando_nombre ? (
                      <span className="text-blue-700 font-semibold">{solicitud.revisando_nombre}</span>
                    ) : (
                      <span className="text-gray-400">-</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                    {solicitud.fecha_creacion
                      ? String(solicitud.fecha_creacion).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19)
                      : 'Sin fecha'}
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-900 max-w-xs truncate">
                    {solicitud.observaciones || '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm space-x-2">
                    <button
                      onClick={() => setModalDetalles(solicitud)}
                      className="text-blue-600 hover:text-blue-900"
                    >
                      Ver detalles
                    </button>
                    <button
                      onClick={() => verHistorial(solicitud.id)}
                      className="text-green-600 hover:text-green-900"
                    >
                      Ver historial
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {/* Modal de Detalles */}
      {modalDetalles && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-xl font-bold text-gray-800">Detalles de Solicitud</h2>
                  <p className="text-gray-600">ID: {modalDetalles.id}</p>
                </div>
                <button
                  onClick={() => setModalDetalles(null)}
                  className="p-2 hover:bg-gray-100 rounded-lg"
                >
                  <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <h3 className="font-medium text-gray-900 mb-2">Información del Asesor</h3>
                  <div className="space-y-2">
                    <p><span className="text-gray-600">DNI:</span> {modalDetalles.dni_asesor}</p>
                    <p><span className="text-gray-600">Nombre:</span> {modalDetalles.nombre_asesor}</p>
                    <p><span className="text-gray-600">Correo:</span> {modalDetalles.correo_usuario || 'No especificado'}</p>
                    <p><span className="text-gray-600">Campaña:</span> {modalDetalles.campaña}</p>
                    <p><span className="text-gray-600">AnyDesk:</span> {modalDetalles.anydesk || 'No especificado'}</p>
                    <p>
                      <span className="text-gray-600">Estado:</span>
                      <span className={`ml-2 px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${modalDetalles.estado === 'aprobada'
                        ? 'bg-green-100 text-green-800'
                        : modalDetalles.estado === 'rechazada'
                          ? 'bg-red-100 text-red-800'
                          : 'bg-yellow-100 text-yellow-800'
                        }`}>
                        {modalDetalles.estado}
                      </span>
                    </p>
                  </div>
                </div>
                {/* Solo mostrar información técnica si la solicitud NO está pendiente */}
                {modalDetalles.estado !== 'pendiente' && (
                  <div>
                    <h3 className="font-medium text-gray-900 mb-2">Información Técnica</h3>
                    <div className="space-y-2">
                      <p><span className="text-gray-600">Windows Actualizado:</span> {modalDetalles.windows_actualizado ? '✅ Sí' : '❌ No'}</p>
                      <p><span className="text-gray-600">Procesador Cumple:</span> {modalDetalles.procesador_cumple ? '✅ Sí' : '❌ No'}</p>
                      <p><span className="text-gray-600">RAM Cumple:</span> {modalDetalles.ram_cumple ? '✅ Sí' : '❌ No'}</p>
                      <p><span className="text-gray-600">Antivirus:</span> {modalDetalles.tiene_antivirus ? '✅ Sí' : '❌ No'}</p>
                      <p><span className="text-gray-600">MAC Address:</span> {modalDetalles.mac_address || 'No especificado'}</p>
                      {(modalDetalles.problemas_anydesk || modalDetalles.problemas_red) && (
                        <div className="border-t pt-2 mt-2">
                          <h4 className="text-sm font-medium text-red-800 mb-1">Problemas Identificados:</h4>
                          {modalDetalles.problemas_anydesk && (
                            <p><span className="text-red-600">❌ Problemas con AnyDesk</span></p>
                          )}
                          {modalDetalles.problemas_red && (
                            <p><span className="text-red-600">❌ Problemas de Red</span></p>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                )}
                {/* Mostrar imágenes adjuntas solo si existen Y la solicitud no está pendiente */}
                {modalDetalles.estado !== 'pendiente' && modalDetalles.imagenes && JSON.parse(modalDetalles.imagenes).length > 0 && (
                  <div className="md:col-span-2 mt-4">
                    <h3 className="font-medium text-gray-900 mb-2">Evidencias de Revisión</h3>
                    <div className="flex flex-wrap gap-4">
                      {JSON.parse(modalDetalles.imagenes).map((img, idx) => (
                        <a
                          key={idx}
                          href={`${API}/uploads/solicitudes/${img}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="relative group"
                        >
                          <img
                            src={`${API}/uploads/solicitudes/${img}`}
                            alt={`Evidencia ${idx + 1}`}
                            className="w-24 h-24 object-cover rounded border hover:scale-110 transition-transform"
                          />
                          <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-20 transition-opacity rounded flex items-center justify-center">
                            <svg className="w-6 h-6 text-white opacity-0 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                            </svg>
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
                {modalDetalles.observaciones && (
                  <div className="md:col-span-2">
                    <h3 className="font-medium text-gray-900 mb-2">Observaciones</h3>
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="text-gray-700">{modalDetalles.observaciones}</p>
                    </div>
                  </div>
                )}
                <div className="md:col-span-2 border-t pt-4">
                  <h3 className="font-medium text-gray-900 mb-2">Fechas</h3>
                  <div className="space-y-2">
                    <p className="text-sm font-medium text-gray-900">Creada el {modalDetalles.fecha_creacion ? String(modalDetalles.fecha_creacion).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19) : 'Sin fecha'}</p>
                    {modalDetalles.fecha_revision && (
                      <p className="text-sm font-medium text-gray-900">
                        {modalDetalles.estado === 'aprobada' ? 'Aprobada' : 'Rechazada'} el {modalDetalles.fecha_revision ? String(modalDetalles.fecha_revision).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19) : 'Sin fecha'}
                      </p>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex justify-end mt-6">
                <button
                  onClick={() => setModalDetalles(null)}
                  className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200"
                >
                  Cerrar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PanelFormacion;