import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import imageCompression from 'browser-image-compression';
import { CheckCircle, XCircle, AlertTriangle, Cpu, MemoryStick, Shield, MonitorSpeaker, Wifi, User, Mail, Calendar, Briefcase, Monitor, Hash } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';


const GestionSolicitudes = ({ solicitudes, token, onSolicitudActualizada, mostrarNotificacion }) => {
    const [solicitudesLista, setSolicitudesLista] = useState(solicitudes);
    const [cargando, setCargando] = useState(false);
    const [filtroEstado, setFiltroEstado] = useState('pendiente');
    const [busqueda, setBusqueda] = useState('');
    const [filtroCampaña, setFiltroCampaña] = useState('');
    const [filtroCampañaDebounced, setFiltroCampañaDebounced] = useState('');
    const [campañasDisponibles, setCampañasDisponibles] = useState([]);
    const [campañasFiltradas, setCampañasFiltradas] = useState([]);
    const [mostrarDropdownCampaña, setMostrarDropdownCampaña] = useState(false);
    const [modalDetalles, setModalDetalles] = useState(null);
    const [modalRevisar, setModalRevisar] = useState(null);
    const [modalHistorial, setModalHistorial] = useState(null);
    
    // Estados para paginación
    const [paginaActual, setPaginaActual] = useState(1);
    const [totalPaginas, setTotalPaginas] = useState(1);
    const [totalSolicitudes, setTotalSolicitudes] = useState(0);
    const [detallesTecnicos, setDetallesTecnicos] = useState({
        windows_actualizado: false,
        procesador_cumple: false,
        ram_cumple: false,
        tiene_antivirus: false,
        problemas_anydesk: false,
        problemas_red: false,
        mac_address: '',
        observaciones: ''
    });
    const [historial, setHistorial] = useState([]);
    const [cargandoHistorial, setCargandoHistorial] = useState(false);
    const [imagenes, setImagenes] = useState([]); // [{file, url}]
    // Mostrar y eliminar imágenes ya guardadas en el modal de revisión
    const [imagenesGuardadas, setImagenesGuardadas] = useState([]);
    const [usuario, setUsuario] = useState(null);
    
    // Estados para cache y gestión de solicitudes tomadas (MEJORADO)
    const [solicitudesEnProceso, setSolicitudesEnProceso] = useState([]);
    const [mostrarBannerLiberacion, setMostrarBannerLiberacion] = useState(false);

    // Funciones de cache para múltiples solicitudes tomadas
    const CACHE_KEY = 'solicitudes_en_proceso';
    
    const guardarEnCache = (solicitudId, datos, imagenesActuales = []) => {
        const cacheData = JSON.parse(localStorage.getItem(CACHE_KEY) || '{}');
        const userKey = `user_${usuario?.id}`;
        
        if (!cacheData[userKey]) {
            cacheData[userKey] = {};
        }
        
        cacheData[userKey][solicitudId] = {
            datos,
            imagenes: imagenesActuales, // Guardar también las imágenes
            timestamp: Date.now(),
            solicitudId
        };
        
        localStorage.setItem(CACHE_KEY, JSON.stringify(cacheData));
        sincronizarCache();
    };

    const cargarDesdeCache = () => {
        try {
            const cached = localStorage.getItem(CACHE_KEY);
            if (cached) {
                const cacheData = JSON.parse(cached);
                const userKey = `user_${usuario?.id}`;
                if (cacheData[userKey]) {
                    const solicitudesUsuario = Object.values(cacheData[userKey]).filter(item => {
                        // Verificar que no haya expirado (24 horas)
                        return Date.now() - item.timestamp < 24 * 60 * 60 * 1000;
                    });
                    return solicitudesUsuario;
                }
            }
        } catch (error) {
            console.error('Error al cargar cache:', error);
        }
        return [];
    };

    const limpiarCache = (solicitudId = null) => {
        const cacheData = JSON.parse(localStorage.getItem(CACHE_KEY) || '{}');
        const userKey = `user_${usuario?.id}`;
        
        if (solicitudId) {
            // Limpiar solo una solicitud específica
            if (cacheData[userKey]) {
                delete cacheData[userKey][solicitudId];
                if (Object.keys(cacheData[userKey]).length === 0) {
                    delete cacheData[userKey];
                }
            }
        } else {
            // Limpiar todas las solicitudes del usuario
            delete cacheData[userKey];
        }
        
        localStorage.setItem(CACHE_KEY, JSON.stringify(cacheData));
        sincronizarCache();
    };

    const sincronizarCache = () => {
        const solicitudesCache = cargarDesdeCache();
        setSolicitudesEnProceso(solicitudesCache);
        setMostrarBannerLiberacion(solicitudesCache.length > 0);
    };

    // Listener para sincronización entre pestañas
    useEffect(() => {
        const handleStorageChange = (e) => {
            if (e.key === CACHE_KEY && usuario?.id) {
                sincronizarCache();
            }
        };

        window.addEventListener('storage', handleStorageChange);
        return () => window.removeEventListener('storage', handleStorageChange);
    }, [usuario]);

    // Verificar cache al cargar el componente y al cambiar usuario
    useEffect(() => {
        if (usuario?.id) {
            sincronizarCache();
        }
    }, [usuario]);

    // Cargar campañas disponibles al inicio
    useEffect(() => {
        const cargarCampañas = async () => {
            try {
                const response = await axios.get(`${API}/api/ti/campanias`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setCampañasDisponibles(response.data.campañas || []);
            } catch (error) {
                console.error('Error al cargar campañas:', error);
            }
        };

        if (token) {
            cargarCampañas();
        }
    }, [token]);

    // Filtrar campañas localmente cuando cambia el texto de búsqueda
    useEffect(() => {
        if (filtroCampaña === '') {
            setCampañasFiltradas([]);
            setMostrarDropdownCampaña(false);
        } else {
            const filtradas = campañasDisponibles.filter(campaña =>
                campaña.toLowerCase().includes(filtroCampaña.toLowerCase())
            );
            setCampañasFiltradas(filtradas);
            setMostrarDropdownCampaña(filtradas.length > 0 && filtroCampaña !== '');
        }
    }, [filtroCampaña, campañasDisponibles]);

    // Cerrar dropdown al hacer clic fuera
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (!event.target.closest('.campaign-filter')) {
                setMostrarDropdownCampaña(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);
    useEffect(() => {
        if (token) {
            try {
                const payload = JSON.parse(atob(token.split('.')[1]));
                setUsuario(payload);
            } catch (err) {
                console.error('Error al decodificar token:', err);
            }
        }
    }, [token]);

    // Debounce para filtro de campaña (aplicar filtro después de 500ms de inactividad)
    useEffect(() => {
        const timer = setTimeout(() => {
            setFiltroCampañaDebounced(filtroCampaña);
        }, 500);

        return () => clearTimeout(timer);
    }, [filtroCampaña]);

    // Cargar solicitudes según filtros
    useEffect(() => {
        const cargarSolicitudes = async () => {
            try {
                setCargando(true);
                
                // Para pendientes, usar límite de 15 con paginación, para otros usar límite de 10
                const limite = filtroEstado === 'pendiente' ? 15 : 10;
                
                const response = await axios.get(`${API}/api/ti/solicitudes`, {
                    params: {
                        estado: filtroEstado,
                        dni_asesor: busqueda,
                        campaña: filtroCampañaDebounced,
                        limit: limite,
                        page: paginaActual  // Enviar 'page' en lugar de 'offset'
                    },
                    headers: { Authorization: `Bearer ${token}` }
                });
                
                setSolicitudesLista(response.data.solicitudes || []);
                
                // Solo manejar paginación para pendientes
                if (filtroEstado === 'pendiente') {
                    const total = response.data.pagination?.totalItems || response.data.total || 0;
                    setTotalSolicitudes(total);
                    setTotalPaginas(Math.ceil(total / limite));
                }
                
            } catch (error) {
                console.error('Error al cargar solicitudes:', error);
                mostrarNotificacion('Error al cargar solicitudes', 'error');
            } finally {
                setCargando(false);
            }
        };

        cargarSolicitudes();
    }, [filtroEstado, busqueda, filtroCampañaDebounced, token, paginaActual]);

    // Reset página cuando cambien filtros
    useEffect(() => {
        setPaginaActual(1);
    }, [filtroEstado, busqueda, filtroCampañaDebounced]);

    // Manejar cambio en filtros
    const handleFiltroChange = (e) => {
        setFiltroEstado(e.target.value);
    };

    // Manejar búsqueda
    const handleBusquedaChange = (e) => {
        setBusqueda(e.target.value);
    };

    // Manejar filtro de campaña
    const handleFiltroCampañaChange = (e) => {
        setFiltroCampaña(e.target.value);
    };

    // Seleccionar campaña del dropdown
    const seleccionarCampaña = (campaña) => {
        setFiltroCampaña(campaña);
        setMostrarDropdownCampaña(false);
    };

    // Limpiar filtro de campaña
    const limpiarFiltroCampaña = () => {
        setFiltroCampaña('');
        setMostrarDropdownCampaña(false);
    };

    // Actualizar campañas disponibles
    const actualizarCampañas = async () => {
        try {
            const response = await axios.get(`${API}/api/ti/campanias`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setCampañasDisponibles(response.data.campañas || []);
            mostrarNotificacion('Campañas actualizadas', 'success');
        } catch (error) {
            console.error('Error al actualizar campañas:', error);
            mostrarNotificacion('Error al actualizar campañas', 'error');
        }
    };
const [previewImagen, setPreviewImagen] = useState(null);
    // Ver detalles de solicitud
    const verDetalles = async (id) => {
        try {
            const response = await axios.get(`${API}/api/ti/solicitudes/${id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setModalDetalles(response.data.solicitud); // <-- Solo la solicitud
        } catch (error) {
            console.error('Error al obtener detalles:', error);
            mostrarNotificacion('Error al cargar detalles', 'error');
        }
    };

    // Tomar solicitud para revisión
    const tomarSolicitud = async (solicitud) => {
        try {
            await axios.post(`${API}/api/ti/solicitudes/${solicitud.id}/tomar`, {}, {
                headers: { Authorization: `Bearer ${token}` }
            });
            // Si la toma es exitosa, abrir el modal de revisión
            abrirRevisarSolicitud(solicitud);
        } catch (error) {
            const msg = error.response?.data?.message || 'Error al tomar solicitud';
            mostrarNotificacion(msg, 'error');
        }
    };

    // Liberar solicitud
    const liberarSolicitud = async (solicitudId) => {
        try {
            await axios.post(`${API}/api/ti/solicitudes/${solicitudId}/liberar`, {}, {
                headers: { Authorization: `Bearer ${token}` }
            });
            
            // Limpiar cache específico al liberar
            limpiarCache(solicitudId);
            
            // Actualizar lista de solicitudes
            const limite = filtroEstado === 'pendiente' ? 15 : 10;
            
            const response = await axios.get(`${API}/api/ti/solicitudes`, {
                params: {
                    estado: filtroEstado,
                    dni_asesor: busqueda,
                    campaña: filtroCampañaDebounced,
                    limit: limite,
                    page: paginaActual
                },
                headers: { Authorization: `Bearer ${token}` }
            });
            
            setSolicitudesLista(response.data.solicitudes || []);
            
            // Solo manejar paginación para pendientes
            if (filtroEstado === 'pendiente') {
                const total = response.data.pagination?.totalItems || response.data.total || 0;
                setTotalSolicitudes(total);
                setTotalPaginas(Math.ceil(total / limite));
            }
            mostrarNotificacion('Solicitud liberada', 'success');
        } catch (error) {
            mostrarNotificacion('Error al liberar solicitud', 'error');
        }
    };

    // Abrir modal para revisar solicitud (modificado)
    const abrirRevisarSolicitud = (solicitud) => {
        setModalRevisar(solicitud);
        
        // Verificar si hay datos en cache para esta solicitud
        const cached = cargarDesdeCache();
        const solicitudEnCache = cached.find(s => s.solicitudId === solicitud.id);
        
        if (solicitudEnCache && solicitudEnCache.datos) {
            setDetallesTecnicos(solicitudEnCache.datos);
            // Restaurar imágenes del cache si existen
            if (solicitudEnCache.imagenes && solicitudEnCache.imagenes.length > 0) {
                setImagenes(solicitudEnCache.imagenes);
            }
        } else {
            setDetallesTecnicos({
                windows_actualizado: solicitud.windows_actualizado || false,
                procesador_cumple: solicitud.procesador_cumple || false,
                ram_cumple: solicitud.ram_cumple || false,
                tiene_antivirus: solicitud.tiene_antivirus || false,
                problemas_anydesk: false,
                problemas_red: false,
                mac_address: solicitud.mac_address || '',
                observaciones: solicitud.observaciones || ''
            });
        }
        
        // Agregar al cache si no existe
        if (!solicitudEnCache) {
            guardarEnCache(solicitud.id, detallesTecnicos, []);
        }
        
        // Ocultar banner mientras está en el modal
        setMostrarBannerLiberacion(false);
        
        // Cargar imágenes guardadas
        if (solicitud.imagenes) {
            try {
                setImagenesGuardadas(JSON.parse(solicitud.imagenes));
            } catch {
                setImagenesGuardadas([]);
            }
        } else {
            setImagenesGuardadas([]);
        }
        
        // No limpiar imágenes si vienen del cache
        if (!solicitudEnCache || !solicitudEnCache.imagenes) {
            setImagenes([]);
        }
    };

    // Cerrar modal de revisión SIN liberar automáticamente
    const cerrarModalRevisar = () => {
        // Guardar el estado actual en cache antes de cerrar (incluyendo imágenes)
        if (modalRevisar && modalRevisar.id) {
            guardarEnCache(modalRevisar.id, detallesTecnicos, imagenes);
        }
        
        setModalRevisar(null);
        setImagenes([]);
        setImagenesGuardadas([]);
        
        // Mostrar banner solo si hay solicitudes en proceso
        const cached = cargarDesdeCache();
        setMostrarBannerLiberacion(cached.length > 0);
    };

    // Continuar revisando solicitud desde cache (para el banner)
    const continuarRevisando = (solicitudId) => {
        const solicitud = solicitudesLista.find(s => s.id === solicitudId);
        if (solicitud) {
            abrirRevisarSolicitud(solicitud);
        }
    };

    // Liberar solicitud específica desde banner
    const liberarSolicitudBanner = (solicitudId) => {
        liberarSolicitud(solicitudId);
        limpiarCache(solicitudId);
    };

    // Liberar todas las solicitudes
    const liberarTodasSolicitudes = () => {
        const cached = cargarDesdeCache();
        cached.forEach(item => {
            liberarSolicitud(item.solicitudId);
        });
        limpiarCache();
    };

    // Manejar cambio en detalles técnicos (solo para campos no booleanos)
    const handleDetallesChange = (e) => {
        const { name, value, type, checked } = e.target;

        let processedValue = value;

        // Formatear MAC address automáticamente
        if (name === 'mac_address') {
            processedValue = formatearMacAddress(value);
        }

        const nuevosDetalles = {
            ...detallesTecnicos,
            [name]: type === 'checkbox' ? checked : processedValue
        };

        setDetallesTecnicos(nuevosDetalles);

        // Guardar en cache cada vez que cambie algo (incluyendo imágenes)
        if (modalRevisar && modalRevisar.id) {
            guardarEnCache(modalRevisar.id, nuevosDetalles, imagenes);
        }
    };

    // Función para formatear MAC address
    const formatearMacAddress = (valor) => {
        if (!valor) return '';
        
        // Eliminar espacios en blanco al inicio y final
        let mac = valor.trim();
        
        // Si está vacío después del trim, retornar vacío
        if (!mac) return '';
        
        // Eliminar todos los caracteres que no sean letras, números
        mac = mac.replace(/[^a-fA-F0-9]/g, '');
        
        // Si tiene exactamente 12 caracteres, formatear con dos puntos
        if (mac.length === 12) {
            return mac.match(/.{1,2}/g).join(':').toUpperCase();
        }
        
        // Si tiene menos de 12 caracteres, mantener lo que se está escribiendo pero sin formatear
        if (mac.length < 12) {
            return mac.toUpperCase();
        }
        
        // Si tiene más de 12 caracteres, tomar solo los primeros 12 y formatear
        if (mac.length > 12) {
            mac = mac.substring(0, 12);
            return mac.match(/.{1,2}/g).join(':').toUpperCase();
        }
        
        return mac.toUpperCase();
    };

    // Manejar selección de imágenes
    const handleImagenesChange = async (e) => {
        const files = Array.from(e.target.files);
        await procesarArchivos(files);
    };

    // Procesar archivos (común para selección y pegado)
    const procesarArchivos = async (files) => {
        const nuevasImagenes = [];
        for (let file of files) {
            if (imagenes.length + nuevasImagenes.length >= 5) {
                mostrarNotificacion('Máximo 5 imágenes permitidas', 'warning');
                break;
            }
            try {
                const compressed = await imageCompression(file, {
                    maxSizeMB: 1,
                    maxWidthOrHeight: 1280,
                    useWebWorker: true
                });
                // Mantener nombre original pero sanitizado
                let ext = file.name.split('.').pop();
                let base = file.name.substring(0, file.name.lastIndexOf('.'));
                // Sanitizar: solo letras, números, guion y guion bajo
                base = base.replace(/[^a-zA-Z0-9_-]/g, '_');
                let cleanName = `${base}.${ext}`;
                const finalFile = new File([compressed], cleanName, { type: compressed.type });
                nuevasImagenes.push({
                    file: finalFile,
                    url: URL.createObjectURL(finalFile)
                });
            } catch (err) {
                mostrarNotificacion('Error al comprimir imagen', 'error');
            }
        }
        const nuevasImagenesConCache = [...imagenes, ...nuevasImagenes];
        setImagenes(nuevasImagenesConCache);
        
        // Actualizar cache con las nuevas imágenes
        if (modalRevisar && modalRevisar.id) {
            guardarEnCache(modalRevisar.id, detallesTecnicos, nuevasImagenesConCache);
        }
    };

    // Manejar pegado de imágenes
    const handlePaste = async (e) => {
        const items = Array.from(e.clipboardData?.items || []);
        const imageFiles = items
            .filter(item => item.type.startsWith('image/'))
            .map(item => item.getAsFile())
            .filter(file => file !== null);
        
        if (imageFiles.length > 0) {
            e.preventDefault();
            await procesarArchivos(imageFiles);
            mostrarNotificacion(`${imageFiles.length} imagen(es) pegada(s)`, 'success');
        }
    };

    // Agregar listener para pegado cuando el modal esté abierto
    useEffect(() => {
        if (modalRevisar) {
            document.addEventListener('paste', handlePaste);
            return () => document.removeEventListener('paste', handlePaste);
        }
    }, [modalRevisar, imagenes]);

    // Eliminar imagen
    const handleEliminarImagen = (idx) => {
        const nuevasImagenes = imagenes.filter((_, i) => i !== idx);
        setImagenes(nuevasImagenes);
        
        // Actualizar cache con las nuevas imágenes
        if (modalRevisar && modalRevisar.id) {
            guardarEnCache(modalRevisar.id, detallesTecnicos, nuevasImagenes);
        }
    };

    // Eliminar imagen guardada (llama al backend)
    const handleEliminarImagenGuardada = async (filename) => {
        if (!modalRevisar) return;
        try {
            await axios.delete(`${API}/api/ti/solicitudes/${modalRevisar.id}/imagen/${filename}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setImagenesGuardadas(prev => prev.filter(img => img !== filename));
            mostrarNotificacion('Imagen eliminada', 'success');
        } catch (err) {
            mostrarNotificacion('Error al eliminar imagen', 'error');
        }
    };

    // Enviar revisión de solicitud
    const enviarRevision = async (estado) => {
        try {
            const formData = new FormData();
            formData.append('estado', estado);
            formData.append('windows_actualizado', Boolean(detallesTecnicos.windows_actualizado));
            formData.append('procesador_cumple', Boolean(detallesTecnicos.procesador_cumple));
            formData.append('ram_cumple', Boolean(detallesTecnicos.ram_cumple));
            formData.append('tiene_antivirus', Boolean(detallesTecnicos.tiene_antivirus));
            formData.append('problemas_anydesk', Boolean(detallesTecnicos.problemas_anydesk));
            formData.append('problemas_red', Boolean(detallesTecnicos.problemas_red));
            formData.append('mac_address', detallesTecnicos.mac_address || '');
            formData.append('observaciones', detallesTecnicos.observaciones || '');
            imagenes.forEach((img, idx) => {
                formData.append('imagenes', img.file);
            });
            await axios.put(`${API}/api/ti/solicitudes/${modalRevisar.id}`, formData, {
                headers: { 'Authorization': `Bearer ${token}`,
                    'Content-Type': 'multipart/form-data' }
            });
            
            // Limpiar cache específico al enviar revisión exitosamente
            limpiarCache(modalRevisar.id);
            
            mostrarNotificacion(`Solicitud ${estado} correctamente`, 'success');
            setModalRevisar(null);
            setImagenes([]);
            setImagenesGuardadas([]);
            // Refrescar solicitudes después de aprobar/rechazar
            const limite = filtroEstado === 'pendiente' ? 15 : 10;
            
            const response = await axios.get(`${API}/api/ti/solicitudes`, {
                params: {
                    estado: filtroEstado,
                    dni_asesor: busqueda,
                    campaña: filtroCampaña,
                    limit: limite,
                    page: paginaActual
                },
                headers: { Authorization: `Bearer ${token}` }
            });
            
            setSolicitudesLista(response.data.solicitudes || []);
            
            // Solo manejar paginación para pendientes
            if (filtroEstado === 'pendiente') {
                const total = response.data.pagination?.totalItems || response.data.total || 0;
                setTotalSolicitudes(total);
                setTotalPaginas(Math.ceil(total / limite));
            }
            if (onSolicitudActualizada) {
                onSolicitudActualizada();
            }
        } catch (error) {
            let msg = 'Error al procesar solicitud';
            if (error.response && error.response.data && error.response.data.message) {
                msg = error.response.data.message;
            }
            console.error('Error al revisar solicitud:', error);
            mostrarNotificacion(msg, 'error');
        }
    };

    // Ver historial de solicitud
    const verHistorial = async (id) => {
        setCargandoHistorial(true);
        try {
            const response = await axios.get(`${API}/api/ti/solicitudes/${id}/historial`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setHistorial(response.data.historial || []);
            setModalHistorial(true);
        } catch (error) {
            mostrarNotificacion('Error al cargar historial', 'error');
        } finally {
            setCargandoHistorial(false);
        }
    };

    // Función helper para manejar selección múltiple de checkboxes
    const toggleCheckbox = (fieldName) => {
        setDetallesTecnicos(prev => ({
            ...prev,
            [fieldName]: !prev[fieldName]
        }));

        // Guardar en cache si hay una solicitud en revisión
        if (modalRevisar && modalRevisar.id) {
            const nuevosDetalles = {
                ...detallesTecnicos,
                [fieldName]: !detallesTecnicos[fieldName]
            };
            guardarEnCache(modalRevisar.id, nuevosDetalles, imagenes);
        }
    };

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            {/* Banner de solicitudes en proceso */}
            {mostrarBannerLiberacion && solicitudesEnProceso.length > 0 && (
                <div className="mb-6 bg-amber-50 border border-amber-200 rounded-lg p-4">
                    <div className="flex items-start justify-between">
                        <div className="flex items-center">
                            <svg className="w-5 h-5 text-amber-600 mr-2 mt-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 15.5c-.77.833.192 2.5 1.732 2.5z" />
                            </svg>
                            <div>
                                <p className="font-medium text-amber-800">
                                    Tienes {solicitudesEnProceso.length} solicitud{solicitudesEnProceso.length > 1 ? 'es' : ''} en proceso
                                </p>
                                <div className="text-sm text-amber-700 mt-1 space-y-1">
                                    {solicitudesEnProceso.map((item, index) => (
                                        <div key={item.solicitudId} className="flex items-center justify-between bg-amber-100 px-2 py-1 rounded">
                                            <span>#{item.solicitudId} - {solicitudesLista.find(s => s.id === item.solicitudId)?.nombre_asesor || 'Sin nombre'}</span>
                                            <div className="flex space-x-1">
                                                <button
                                                    onClick={() => continuarRevisando(item.solicitudId)}
                                                    className="px-2 py-1 bg-blue-600 text-white text-xs rounded hover:bg-blue-700 transition-colors"
                                                >
                                                    Continuar
                                                </button>
                                                <button
                                                    onClick={() => liberarSolicitudBanner(item.solicitudId)}
                                                    className="px-2 py-1 bg-gray-600 text-white text-xs rounded hover:bg-gray-700 transition-colors"
                                                >
                                                    Liberar
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                        {solicitudesEnProceso.length > 1 && (
                            <button
                                onClick={liberarTodasSolicitudes}
                                className="px-3 py-1 bg-red-600 text-white text-sm rounded hover:bg-red-700 transition-colors"
                            >
                                Liberar Todas
                            </button>
                        )}
                    </div>
                </div>
            )}

            {/* Filtros y búsqueda */}
            <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6 space-y-4 md:space-y-0">
                <div className="flex space-x-4">
                    <select
                        value={filtroEstado}
                        onChange={handleFiltroChange}
                        className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent"
                    >
                        <option value="pendiente">Pendientes</option>
                        <option value="aprobada">Aprobadas</option>
                        <option value="rechazada">Rechazadas</option>
                    </select>
                    {/* Filtro de campaña con autocompletado */}
                    <div className="relative campaign-filter">
                        <div className="flex">
                            <input
                                type="text"
                                placeholder="Filtrar por campaña..."
                                value={filtroCampaña}
                                onChange={handleFiltroCampañaChange}
                                onFocus={() => filtroCampaña && setMostrarDropdownCampaña(campañasFiltradas.length > 0)}
                                className="px-4 py-2 border border-gray-300 rounded-l-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent w-48"
                            />
                            {filtroCampaña && (
                                <button
                                    onClick={limpiarFiltroCampaña}
                                    className="px-2 border-t border-b border-gray-300 text-gray-400 hover:text-red-500"
                                    title="Limpiar filtro"
                                >
                                    ✕
                                </button>
                            )}
                            <button
                                onClick={actualizarCampañas}
                                className="px-3 py-2 bg-gray-100 hover:bg-gray-200 border border-gray-300 rounded-r-lg text-gray-600"
                                title="Actualizar campañas"
                            >
                                🔄
                            </button>
                        </div>
                        
                        {/* Dropdown de campañas */}
                        {mostrarDropdownCampaña && (
                            <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-40 overflow-y-auto">
                                {campañasFiltradas.map((campaña, index) => (
                                    <button
                                        key={index}
                                        onClick={() => seleccionarCampaña(campaña)}
                                        className="w-full px-4 py-2 text-left hover:bg-gray-100 focus:bg-gray-100 focus:outline-none"
                                    >
                                        {campaña}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
                <div className="relative">
                    <input
                        type="text"
                        placeholder="Buscar por DNI de asesor..."
                        value={busqueda}
                        onChange={handleBusquedaChange}
                        className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full md:w-64 focus:ring-2 focus:ring-blue-200 focus:border-transparent"
                    />
                    <svg className="w-5 h-5 text-gray-400 absolute left-3 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
            </div>

            {/* Botón de Actualizar */}
            <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-bold text-gray-800">Solicitudes</h2>
                <button
                    onClick={() => {
                        // Refresca la lista manualmente
                        setCargando(true);
                        
                        const limite = filtroEstado === 'pendiente' ? 15 : 10;
                        
                        axios.get(`${API}/api/ti/solicitudes`, {
                            params: {
                                estado: filtroEstado,
                                dni_asesor: busqueda,
                                campaña: filtroCampañaDebounced,
                                limit: limite,
                                page: paginaActual
                            },
                            headers: { Authorization: `Bearer ${token}` }
                        })
                            .then(response => {
                                setSolicitudesLista(response.data.solicitudes || []);
                                
                                // Solo manejar paginación para pendientes
                                if (filtroEstado === 'pendiente') {
                                    const total = response.data.pagination?.totalItems || response.data.total || 0;
                                    setTotalSolicitudes(total);
                                    setTotalPaginas(Math.ceil(total / limite));
                                }
                                
                                mostrarNotificacion('Lista actualizada', 'info');
                            })
                            .catch(() => mostrarNotificacion('Error al actualizar solicitudes', 'error'))
                            .finally(() => setCargando(false));
                    }}
                    className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow"
                >
                    <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582M20 20v-5h-.581M5 19a9 9 0 1010-10" /></svg>
                    Actualizar
                </button>
            </div>

            {/* Lista de solicitudes */}
            {cargando ? (
                <div className="flex justify-center py-8">
                    <div className="animate-spin rounded-full h-10 w-10 border-4 border-blue-500 border-t-transparent"></div>
                </div>
            ) : solicitudesLista.length === 0 ? (
                <div className="text-center py-12">
                    <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <h3 className="mt-2 text-lg font-medium text-gray-900">No hay solicitudes</h3>
                    <p className="mt-1 text-sm text-gray-500">
                        {filtroEstado === 'pendiente'
                            ? 'No hay solicitudes pendientes de revisión'
                            : `No hay solicitudes ${filtroEstado === 'aprobada' ? 'aprobadas' : 'rechazadas'}`}
                    </p>
                </div>
            ) : (
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">DNI Asesor</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nombre</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Campaña</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Fecha</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Estado</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {solicitudesLista.map((solicitud) => (
                                <tr key={solicitud.id}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                        {solicitud.dni_asesor}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                        {solicitud.nombre_asesor}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                        {solicitud.campaña}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                        {solicitud.fecha_creacion
                                            ? String(solicitud.fecha_creacion).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19)
                                            : 'Sin fecha'}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${solicitud.estado === 'aprobada'
                                            ? 'bg-green-100 text-green-800'
                                            : solicitud.estado === 'rechazada'
                                                ? 'bg-red-100 text-red-800'
                                                : 'bg-yellow-100 text-yellow-800'
                                            }`}>
                                            {solicitud.estado}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                                        {solicitud.estado === 'pendiente' ? (
                                            // Para solicitudes pendientes
                                            solicitud.revisando_por && solicitud.revisando_por !== usuario?.id ? (
                                                <span className="text-orange-600 text-xs">
                                                    Revisando: {solicitud.revisando_nombre}
                                                </span>
                                            ) : solicitudesEnProceso.some(s => s.solicitudId === solicitud.id) ? (
                                                <span className="text-blue-600 text-xs">
                                                    En proceso por ti
                                                </span>
                                            ) : (
                                                <button
                                                    type="button"
                                                    onClick={e => {
                                                        e.preventDefault();
                                                        e.stopPropagation();
                                                        tomarSolicitud(solicitud);
                                                    }}
                                                    className="text-green-600 hover:text-green-900"
                                                    tabIndex={0}
                                                >
                                                    Revisar
                                                </button>
                                            )
                                        ) : (
                                            // Para solicitudes procesadas, solo mostrar Ver
                                            <button
                                                type="button"
                                                onClick={e => { e.preventDefault(); e.stopPropagation(); verDetalles(solicitud.id); }}
                                                className="text-blue-600 hover:text-blue-900"
                                                tabIndex={0}
                                            >
                                                Ver
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Paginación para solicitudes pendientes */}
            {filtroEstado === 'pendiente' && totalPaginas > 1 && solicitudesLista.length > 0 && (
                <div className="flex items-center justify-between mt-6 px-4 py-3 bg-white border border-gray-200 rounded-lg">
                    <div className="flex items-center text-sm text-gray-700">
                        <span>
                            Mostrando {((paginaActual - 1) * 15) + 1} - {Math.min(paginaActual * 15, totalSolicitudes)} de {totalSolicitudes} solicitudes
                        </span>
                    </div>
                    <div className="flex items-center space-x-2">
                        <button
                            onClick={() => setPaginaActual(prev => Math.max(prev - 1, 1))}
                            disabled={paginaActual === 1}
                            className={`px-3 py-2 rounded-md text-sm font-medium ${
                                paginaActual === 1
                                    ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                            }`}
                        >
                            Anterior
                        </button>
                        
                        <div className="flex items-center space-x-1">
                            {Array.from({ length: totalPaginas }, (_, i) => i + 1)
                                .filter(num => {
                                    // Mostrar siempre primera y última página
                                    if (num === 1 || num === totalPaginas) return true;
                                    // Mostrar páginas cerca de la actual
                                    return Math.abs(num - paginaActual) <= 2;
                                })
                                .map((num, index, array) => {
                                    // Agregar puntos suspensivos si hay saltos
                                    const shouldShowEllipsis = index > 0 && array[index - 1] !== num - 1;
                                    return (
                                        <React.Fragment key={num}>
                                            {shouldShowEllipsis && (
                                                <span className="px-2 py-1 text-gray-500">...</span>
                                            )}
                                            <button
                                                onClick={() => setPaginaActual(num)}
                                                className={`px-3 py-2 rounded-md text-sm font-medium ${
                                                    paginaActual === num
                                                        ? 'bg-blue-600 text-white'
                                                        : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                                                }`}
                                            >
                                                {num}
                                            </button>
                                        </React.Fragment>
                                    );
                                })}
                        </div>
                        
                        <button
                            onClick={() => setPaginaActual(prev => Math.min(prev + 1, totalPaginas))}
                            disabled={paginaActual === totalPaginas}
                            className={`px-3 py-2 rounded-md text-sm font-medium ${
                                paginaActual === totalPaginas
                                    ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                            }`}
                        >
                            Siguiente
                        </button>
                    </div>
                </div>
            )}

            {/* Modal de Detalles */}
            {modalDetalles && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex justify-between items-start">
                                <div>
                                    <h2 className="text-xl font-bold text-gray-800">Detalles de Solicitud</h2>
                                    <p className="text-gray-600">ID: {modalDetalles.id}</p>
                                    <p className="text-gray-600 mt-1">
                                        <span className="font-medium">Creada por Formación:</span> {modalDetalles.creador_nombre || 'Desconocido'}
                                    </p>
                                </div>
                                <button
                                    onClick={() => setModalDetalles(null)}
                                    className="p-2 hover:bg-gray-100 rounded-lg"
                                >
                                    <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </button>
                            </div>

                            <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <h3 className="font-medium text-gray-900 mb-2">Información del Asesor</h3>
                                    <div className="space-y-2">
                                        <p><span className="text-gray-600">DNI:</span> {modalDetalles.dni_asesor}</p>
                                        <p><span className="text-gray-600">Nombre:</span> {modalDetalles.nombre_asesor}</p>
                                        <p><span className="text-gray-600">Campaña:</span> {modalDetalles.campaña}</p>
                                        <p><span className="text-gray-600">AnyDesk:</span> {modalDetalles.anydesk || 'No especificado'}</p>
                                    </div>
                                </div>

                                <div>
                                    <h3 className="font-medium text-gray-900 mb-2">Información Técnica</h3>
                                    <div className="space-y-2">
                                        <p>
                                            <span className="text-gray-600">Estado:</span>
                                            <span className={`ml-2 px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${modalDetalles.estado === 'aprobada'
                                                ? 'bg-green-100 text-green-800'
                                                : modalDetalles.estado === 'rechazada'
                                                    ? 'bg-red-100 text-red-800'
                                                    : 'bg-yellow-100 text-yellow-800'
                                                }`}>
                                                {modalDetalles.estado}
                                            </span>
                                        </p>
                                        <p><span className="text-gray-600">Windows Actualizado:</span> {modalDetalles.windows_actualizado ? '✅ Sí' : '❌ No'}</p>
                                        <p><span className="text-gray-600">Procesador Cumple:</span> {modalDetalles.procesador_cumple ? '✅ Sí' : '❌ No'}</p>
                                        <p><span className="text-gray-600">RAM Cumple:</span> {modalDetalles.ram_cumple ? '✅ Sí' : '❌ No'}</p>
                                        <p><span className="text-gray-600">Antivirus:</span> {modalDetalles.tiene_antivirus ? '✅ Sí' : '❌ No'}</p>
                                        <p><span className="text-gray-600">MAC Address:</span> {modalDetalles.mac_address || 'No especificado'}</p>
                                        <p><span className="text-gray-600">Correo:</span> {modalDetalles.correo_usuario || 'No especificado'}</p>
                                    </div>
                                    
                                    {/* Problemas Identificados - Solo si está procesada */}
                                    {modalDetalles.estado !== 'pendiente' && (modalDetalles.problemas_anydesk || modalDetalles.problemas_red) && (
                                        <div className="mt-4 pt-3 border-t border-gray-200">
                                            <h4 className="text-sm font-medium text-gray-900 mb-2">Problemas Identificados</h4>
                                            <div className="space-y-1">
                                                {modalDetalles.problemas_anydesk && (
                                                    <p className="text-sm"><span className="text-red-600">⚠️ Problemas con AnyDesk</span></p>
                                                )}
                                                {modalDetalles.problemas_red && (
                                                    <p className="text-sm"><span className="text-red-600">⚠️ Problemas de Red</span></p>
                                                )}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {modalDetalles.observaciones && (
                                    <div className="md:col-span-2">
                                        <h3 className="font-medium text-gray-900 mb-2">Observaciones</h3>
                                        <div className="bg-gray-50 p-4 rounded-lg">
                                            <p className="text-gray-700">{modalDetalles.observaciones}</p>
                                        </div>
                                    </div>
                                )}

                                <div className="md:col-span-2 border-t pt-4">
                                    <h3 className="font-medium text-gray-900 mb-2">Historial</h3>
                                    <div className="space-y-4">
                                        <div className="flex items-start">
                                            <div className="flex-shrink-0 h-10 w-10 rounded-full bg-blue-100 flex items-center justify-center">
                                                <svg className="h-5 w-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                                </svg>
                                            </div>
                                            <div className="ml-4">
                                                <p className="text-sm font-medium text-gray-900">Creada el {modalDetalles.fecha_creacion ? String(modalDetalles.fecha_creacion).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19) : 'Sin fecha'}</p>
                                                <p className="text-sm text-gray-500">Por: {modalDetalles.creador_nombre || 'Sistema'}</p>
                                            </div>
                                        </div>

                                        {modalDetalles.fecha_revision && !isNaN(new Date(modalDetalles.fecha_revision)) && (
                                            <div className="flex items-start">
                                                <div className="flex-shrink-0 h-10 w-10 rounded-full bg-purple-100 flex items-center justify-center">
                                                    <svg className="h-5 w-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                                    </svg>
                                                </div>
                                                <div className="ml-4">
                                                    <p className="text-sm font-medium text-gray-900">
                                                        {modalDetalles.estado === 'aprobada' ? 'Aprobada' : 'Rechazada'} el {modalDetalles.fecha_revision ? String(modalDetalles.fecha_revision).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19) : 'Sin fecha'}
                                                    </p>
                                                    <p className="text-sm text-gray-500">Por: {modalDetalles.revisor_nombre || 'Sistema'}</p>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Mostrar imágenes solo si la solicitud está gestionada y tiene imágenes */}
                            {modalDetalles.estado !== 'pendiente' && modalDetalles.imagenes && (() => {
                                try {
                                    const imagenesList = JSON.parse(modalDetalles.imagenes);
                                    return imagenesList.length > 0 ? (
                                        <div className="mt-6 pt-4 border-t">
                                            <h3 className="font-medium text-gray-900 mb-3">Evidencias de Revisión</h3>
                                            <div className="flex flex-wrap gap-4">
                                                {imagenesList.map((img, idx) => (
                                                    <div key={idx} className="relative w-24 h-24 border rounded overflow-hidden cursor-pointer"
                                                         onClick={() => window.open(`${API}/uploads/solicitudes/${img}`, '_blank')}>
                                                        <img 
                                                            src={`${API}/uploads/solicitudes/${img}`} 
                                                            alt={`Evidencia ${idx + 1}`} 
                                                            className="object-cover w-full h-full hover:scale-110 transition-transform"
                                                        />
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    ) : null;
                                } catch {
                                    return null;
                                }
                            })()}

                            <div className="flex justify-end mt-6">
                                <button
                                    onClick={() => verHistorial(modalDetalles.id)}
                                    className="px-4 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200"
                                >
                                    Ver historial
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Historial */}
            {modalHistorial && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex justify-between items-center mb-4">
                                <h2 className="text-xl font-bold text-gray-800">Historial de Solicitud</h2>
                                <button
                                    onClick={() => setModalHistorial(false)}
                                    className="p-2 hover:bg-gray-100 rounded-lg"
                                >
                                    <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </button>
                            </div>
                            {cargandoHistorial ? (
                                <div className="flex justify-center py-8">
                                    <div className="animate-spin rounded-full h-10 w-10 border-4 border-blue-500 border-t-transparent"></div>
                                </div>
                            ) : historial.length === 0 ? (
                                <div className="text-center text-gray-500">No hay historial para esta solicitud.</div>
                            ) : (
                                <ul className="divide-y divide-gray-200">
                                    {historial.map((h) => (
                                        <li key={h.id} className="py-4">
                                            <div className="flex items-center justify-between">
                                                <div>
                                                    <p className="font-medium text-gray-800">{h.accion} ({h.estado_nuevo})</p>
                                                    <p className="text-sm text-gray-600">Por: {h.usuario_nombre || 'Sistema'} ({h.rol || '-'})</p>
                                                    <p className="text-xs text-gray-400">{h.fecha_accion ? new Date(h.fecha_accion).toLocaleString('es-PE', { timeZone: 'America/Lima', hour12: false }) : ''}</p>
                                                </div>
                                                {h.observaciones && (
                                                    <div className="ml-4 text-sm text-gray-700 max-w-xs break-words">{h.observaciones}</div>
                                                )}
                                            </div>
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Revisión */}
            {modalRevisar && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex justify-between items-start mb-6">
                                <div className="flex items-start space-x-4">
                                    <div className="flex-shrink-0 w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl flex items-center justify-center shadow-lg">
                                        <User className="w-6 h-6 text-white" />
                                    </div>
                                    <div>
                                        <h2 className="text-2xl font-bold text-gray-800 mb-1">Revisar Solicitud</h2>
                                        <div className="flex items-center space-x-2 text-gray-600">
                                            <Hash className="w-4 h-4" />
                                            <span className="font-medium">ID: {modalRevisar.id}</span>
                                        </div>
                                        <p className="text-gray-600 mt-1 flex items-center">
                                            <User className="w-4 h-4 mr-1" />
                                            <span className="font-medium">Asesor:</span> {modalRevisar.nombre_asesor} (DNI: {modalRevisar.dni_asesor})
                                        </p>
                                        <p className="text-gray-600 mt-1 flex items-center">
                                            <Briefcase className="w-4 h-4 mr-1" />
                                            <span className="font-medium">Creada por Formación:</span> {modalRevisar.creador_nombre || 'Desconocido'}
                                        </p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => cerrarModalRevisar()}
                                    className="p-2 hover:bg-gray-100 rounded-lg transition-colors duration-200"
                                >
                                    <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </button>
                            </div>

                            <div className="mt-6 space-y-6">
                                {/* Información del Asesor */}
                                <div className="bg-gradient-to-br from-blue-50 to-indigo-50 border border-blue-200 rounded-xl p-6 shadow-sm">
                                    <div className="flex items-center mb-4">
                                        <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center mr-3">
                                            <User className="w-5 h-5 text-blue-600" />
                                        </div>
                                        <h3 className="text-lg font-semibold text-gray-900">Información del Asesor</h3>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div className="space-y-4">
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <Hash className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">DNI</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.dni_asesor}</p>
                                                </div>
                                            </div>
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <User className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">Nombre Completo</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.nombre_asesor}</p>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="space-y-4">
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <Briefcase className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">Campaña</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.campaña}</p>
                                                </div>
                                            </div>
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <Monitor className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">AnyDesk</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.anydesk || 'No especificado'}</p>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="border-t border-blue-200 mt-6 pt-4">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <Mail className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">Correo Electrónico</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.correo_usuario || 'No especificado'}</p>
                                                </div>
                                            </div>
                                            <div className="flex items-center space-x-3">
                                                <div className="w-8 h-8 bg-gray-100 rounded-lg flex items-center justify-center">
                                                    <Calendar className="w-4 h-4 text-gray-600" />
                                                </div>
                                                <div>
                                                    <p className="text-xs text-gray-500 uppercase tracking-wide">Fecha de Solicitud</p>
                                                    <p className="text-sm font-medium text-gray-900">{modalRevisar.fecha_creacion ? String(modalRevisar.fecha_creacion).replace('T', ' ').replace('Z', '').replace(/\.[0-9]+$/, '').slice(0, 19) : 'Sin fecha'}</p>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <h3 className="font-medium text-gray-900 mb-4">Verificación Técnica</h3>
                                        <div className="space-y-4">
                                            {/* Windows Actualizado */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <CheckCircle className={`h-5 w-5 ${detallesTecnicos.windows_actualizado ? 'text-green-500' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">Windows Actualizado</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('windows_actualizado')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.windows_actualizado
                                                            ? 'bg-green-500 text-white shadow-md hover:bg-green-600'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.windows_actualizado ? '✓ Sí' : '○ No'}
                                                </button>
                                            </div>

                                            {/* Procesador Cumple */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <Cpu className={`h-5 w-5 ${detallesTecnicos.procesador_cumple ? 'text-blue-500' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">Procesador Cumple</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('procesador_cumple')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.procesador_cumple
                                                            ? 'bg-blue-500 text-white shadow-md hover:bg-blue-600'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.procesador_cumple ? '✓ Sí' : '○ No'}
                                                </button>
                                            </div>

                                            {/* RAM Cumple */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <MemoryStick className={`h-5 w-5 ${detallesTecnicos.ram_cumple ? 'text-purple-500' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">RAM Cumple</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('ram_cumple')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.ram_cumple
                                                            ? 'bg-purple-500 text-white shadow-md hover:bg-purple-600'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.ram_cumple ? '✓ Sí' : '○ No'}
                                                </button>
                                            </div>

                                            {/* Tiene Antivirus */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <Shield className={`h-5 w-5 ${detallesTecnicos.tiene_antivirus ? 'text-green-600' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">Tiene Antivirus</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('tiene_antivirus')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.tiene_antivirus
                                                            ? 'bg-green-600 text-white shadow-md hover:bg-green-700'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.tiene_antivirus ? '✓ Sí' : '○ No'}
                                                </button>
                                            </div>
                                        </div>
                                    </div>

                                    <div>
                                        <h3 className="font-medium text-gray-900 mb-4">Problemas Identificados</h3>
                                        <div className="space-y-4">
                                            {/* Problemas con AnyDesk */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <MonitorSpeaker className={`h-5 w-5 ${detallesTecnicos.problemas_anydesk ? 'text-red-500' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">Problemas con AnyDesk</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('problemas_anydesk')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.problemas_anydesk
                                                            ? 'bg-red-500 text-white shadow-md hover:bg-red-600'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.problemas_anydesk ? '⚠️ Sí' : '○ No'}
                                                </button>
                                            </div>

                                            {/* Problemas de Red */}
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center space-x-3">
                                                    <Wifi className={`h-5 w-5 ${detallesTecnicos.problemas_red ? 'text-orange-500' : 'text-gray-300'}`} />
                                                    <span className="text-sm font-medium text-gray-700">Problemas de Red</span>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => toggleCheckbox('problemas_red')}
                                                    className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                                                        detallesTecnicos.problemas_red
                                                            ? 'bg-orange-500 text-white shadow-md hover:bg-orange-600'
                                                            : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                    }`}
                                                >
                                                    {detallesTecnicos.problemas_red ? '⚠️ Sí' : '○ No'}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="mt-6">
                                    <div className="flex items-center mb-4">
                                        <div className="w-8 h-8 bg-green-100 rounded-lg flex items-center justify-center mr-3">
                                            <Monitor className="w-5 h-5 text-green-600" />
                                        </div>
                                        <h3 className="text-lg font-semibold text-gray-900">Información Adicional</h3>
                                    </div>
                                    <div className="bg-white border border-gray-200 rounded-lg p-4">
                                        <div>
                                            <label htmlFor="mac_address" className="block text-sm font-medium text-gray-700 mb-2 flex items-center">
                                                <Monitor className="w-4 h-4 mr-2 text-gray-500" />
                                                MAC Address
                                            </label>
                                            <input
                                                type="text"
                                                id="mac_address"
                                                name="mac_address"
                                                value={detallesTecnicos.mac_address}
                                                onChange={handleDetallesChange}
                                                placeholder="Ingrese la MAC Address (ej: AA:BB:CC:DD:EE:FF)"
                                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent transition-colors duration-200"
                                            />
                                        
                                        </div>
                                    </div>
                                </div>

                                <div>
                                    <div className="flex items-center mb-4">
                                        <div className="w-8 h-8 bg-amber-100 rounded-lg flex items-center justify-center mr-3">
                                            <AlertTriangle className="w-5 h-5 text-amber-600" />
                                        </div>
                                        <h3 className="text-lg font-semibold text-gray-900">Observaciones</h3>
                                    </div>
                                    <div className="bg-white border border-gray-200 rounded-lg p-4">
                                        <textarea
                                            id="observaciones"
                                            name="observaciones"
                                            value={detallesTecnicos.observaciones}
                                            onChange={handleDetallesChange}
                                            rows={4}
                                            placeholder="Ingrese observaciones adicionales sobre la revisión técnica..."
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent resize-none transition-colors duration-200"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <div className="flex items-center mb-4">
                                        <div className="w-8 h-8 bg-purple-100 rounded-lg flex items-center justify-center mr-3">
                                            <svg className="w-5 h-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                            </svg>
                                        </div>
                                        <h3 className="text-lg font-semibold text-gray-900">Adjuntar Evidencias</h3>
                                    </div>
                                    <div className="bg-white border border-gray-200 rounded-lg p-4">
                                    
                                    {/* Botón personalizado para seleccionar archivos */}
                                    <div className="flex flex-col gap-3">
                                        <div className="relative">
                                            <input
                                                type="file"
                                                id="imagenes"
                                                accept="image/*"
                                                multiple
                                                onChange={handleImagenesChange}
                                                className="hidden"
                                            />
                                            <label
                                                htmlFor="imagenes"
                                                className="flex items-center justify-center px-4 py-3 bg-blue-50 hover:bg-blue-100 border-2 border-dashed border-blue-300 hover:border-blue-400 rounded-lg cursor-pointer transition-colors duration-200"
                                            >
                                                <svg className="w-5 h-5 text-blue-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                                                </svg>
                                                <span className="text-blue-700 font-medium">Seleccionar imágenes</span>
                                            </label>
                                        </div>
                                        
                                        {/* Hint para pegado */}
                                        <div className="flex items-center text-xs text-gray-500">
                                            <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                            </svg>
                                            También puedes pegar imágenes con Ctrl+V
                                        </div>
                                    </div>

                                    {/* Vista previa de imágenes nuevas */}
                                    {imagenes.length > 0 && (
                                        <div className="mt-4">
                                            <h4 className="text-sm font-medium text-gray-700 mb-2">Imágenes a subir ({imagenes.length}/5)</h4>
                                            <div className="flex flex-wrap gap-3">
                                                {imagenes.map((img, idx) => (
                                                    <div key={idx} className="relative w-20 h-20 border-2 border-gray-200 rounded-lg overflow-hidden group">
                                                        <img 
                                                            src={img.url} 
                                                            alt="captura" 
                                                            className="object-cover w-full h-full cursor-pointer" 
                                                            onClick={() => setPreviewImagen({ url: img.url, idx })}
                                                        />
                                                        <button 
                                                            type="button" 
                                                            onClick={() => handleEliminarImagen(idx)} 
                                                            className="absolute top-1 right-1 w-6 h-6 bg-red-500 hover:bg-red-600 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                                                            title="Eliminar imagen"
                                                        >
                                                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                                                            </svg>
                                                        </button>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
    
            {/* Modal de previsualización de imagen nueva */}
            {previewImagen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-70" onClick={() => setPreviewImagen(null)}>
                    <div className="relative max-w-full max-h-full" onClick={e => e.stopPropagation()}>
                        <img src={previewImagen.url} alt="Previsualización" className="max-w-[90vw] max-h-[80vh] rounded-lg shadow-2xl border-4 border-white" />
                        <button
                            onClick={() => setPreviewImagen(null)}
                            className="absolute top-2 right-2 bg-white bg-opacity-80 hover:bg-opacity-100 text-gray-700 rounded-full p-2 shadow-lg"
                            title="Cerrar"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>
                </div>
            )}
                                    </div>
                                </div>

                                {/* Imágenes ya guardadas */}
                                {imagenesGuardadas.length > 0 && (
                                    <div>
                                        <h4 className="text-sm font-medium text-gray-700 mb-2">Imágenes guardadas</h4>
                                        <div className="flex flex-wrap gap-3">
                                            {imagenesGuardadas.map((img, idx) => (
                                                <div key={idx} className="relative w-20 h-20 border-2 border-green-200 rounded-lg overflow-hidden group">
                                                    <img src={`${API}/uploads/solicitudes/${img}`} alt="captura" className="object-cover w-full h-full" />
                                                    <button 
                                                        type="button" 
                                                        onClick={() => handleEliminarImagenGuardada(img)} 
                                                        className="absolute top-1 right-1 w-6 h-6 bg-red-500 hover:bg-red-600 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200"
                                                        title="Eliminar imagen"
                                                    >
                                                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                                                        </svg>
                                                    </button>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                <div className="flex justify-end space-x-4 pt-6 border-t">
                                    <button
                                        onClick={() => cerrarModalRevisar()}
                                        className="px-6 py-2 text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors duration-200"
                                    >
                                        Cancelar
                                    </button>
                                    <button
                                        onClick={() => enviarRevision('rechazada')}
                                        disabled={detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple && !detallesTecnicos.problemas_anydesk && !detallesTecnicos.problemas_red}
                                        className={`px-6 py-2 text-white rounded-lg transition-colors duration-200 ${
                                            (detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple && !detallesTecnicos.problemas_anydesk && !detallesTecnicos.problemas_red)
                                                ? 'bg-gray-400 cursor-not-allowed'
                                                : 'bg-red-600 hover:bg-red-700'
                                        }`}
                                        title={(detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple && !detallesTecnicos.problemas_anydesk && !detallesTecnicos.problemas_red) ? 
                                            'No se puede rechazar si los requisitos se cumplen y no hay problemas' : 'Rechazar solicitud'}
                                    >
                                        Rechazar
                                    </button>
                                    <button
                                        onClick={() => enviarRevision('aprobada')}
                                        disabled={!(detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple) || detallesTecnicos.problemas_anydesk || detallesTecnicos.problemas_red}
                                        className={`px-6 py-2 text-white rounded-lg transition-colors duration-200 ${
                                            (!(detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple) || detallesTecnicos.problemas_anydesk || detallesTecnicos.problemas_red)
                                                ? 'bg-gray-400 cursor-not-allowed'
                                                : 'bg-green-600 hover:bg-green-700'
                                        }`}
                                        title={(!(detallesTecnicos.procesador_cumple && detallesTecnicos.ram_cumple) || detallesTecnicos.problemas_anydesk || detallesTecnicos.problemas_red) ? 
                                            'Para aprobar: requisitos técnicos deben cumplirse y no debe haber problemas' : 'Aprobar solicitud'}
                                    >
                                        Aprobar
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GestionSolicitudes;