import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const CrearUsuario = ({ onClose, onUsuarioCreado, mostrarNotificacion }) => {
    const [form, setForm] = useState({
        dni: '',
        nombre: '',
        apellido: '',
        contraseña: '',
        confirmarContraseña: '',
        rol: 'formacion'
    });

    const [errores, setErrores] = useState({});
    const [enviando, setEnviando] = useState(false);
    const [mostrarContraseña, setMostrarContraseña] = useState(false);
    const [mostrarConfirmar, setMostrarConfirmar] = useState(false);

    // ✅ VALIDACIONES EN TIEMPO REAL
    useEffect(() => {
        const validar = () => {
            const nuevosErrores = {};

            // DNI formato
            if (form.dni && !/^\d{6,8}$/.test(form.dni)) {
                nuevosErrores.dni = 'DNI debe tener entre 6 y 8 dígitos';
            }

            // Nombre
            if (form.nombre && form.nombre.trim().length < 2) {
                nuevosErrores.nombre = 'El nombre debe tener al menos 2 caracteres';
            }

            // Apellido
            if (form.apellido && form.apellido.trim().length < 2) {
                nuevosErrores.apellido = 'El apellido debe tener al menos 2 caracteres';
            }

            // Contraseña
            if (form.contraseña && form.contraseña.length < 6) {
                nuevosErrores.contraseña = 'La contraseña debe tener al menos 6 caracteres';
            }

            // Confirmar contraseña
            if (form.contraseña !== form.confirmarContraseña) {
                nuevosErrores.confirmarContraseña = 'Las contraseñas no coinciden';
            }

            setErrores(nuevosErrores);
        };

        const timeout = setTimeout(validar, 300);
        return () => clearTimeout(timeout);
    }, [form]);

    // ✅ MANEJAR CAMBIOS EN EL FORMULARIO
    const handleChange = (e) => {
        const { name, value } = e.target;

        // Solo números para DNI
        if (name === 'dni') {
            const soloNumeros = value.replace(/\D/g, '').slice(0, 8);
            setForm(prev => ({ ...prev, [name]: soloNumeros }));
        }
        // Siempre mayúsculas para nombre y apellido
        else if (name === 'nombre' || name === 'apellido') {
            setForm(prev => ({ ...prev, [name]: value.toUpperCase() }));
        }
        else {
            setForm(prev => ({ ...prev, [name]: value }));
        }
    };

    // ✅ VERIFICAR SI EL FORMULARIO ES VÁLIDO
    const formularioValido = () => {
        const camposObligatorios = ['dni', 'nombre', 'apellido', 'contraseña', 'confirmarContraseña'];
        const todosLlenos = camposObligatorios.every(campo => form[campo]?.trim());
        const sinErrores = Object.keys(errores).length === 0;
        return todosLlenos && sinErrores;
    };

    // ✅ CREAR USUARIO
    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!formularioValido()) {
            mostrarNotificacion('Por favor, completa todos los campos correctamente', 'error');
            return;
        }

        setEnviando(true);

        try {
            const datosUsuario = {
                dni: form.dni.trim(),
                nombre: form.nombre.trim(),
                apellido: form.apellido.trim(),
                contraseña: form.contraseña,
                rol: form.rol
            };

            const response = await axios.post(`${API}/api/sistemas/usuarios`, datosUsuario, {
                headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
            });

            const rolTexto = {
                'formacion': 'Formación',
                'ti': 'TI (Sistemas)'
            };

            const mensaje = `Usuario ${form.nombre} ${form.apellido} creado exitosamente como ${rolTexto[form.rol]}`;

            mostrarNotificacion(mensaje, 'success');

            // Limpiar formulario
            setForm({
                dni: '',
                nombre: '',
                apellido: '',
                contraseña: '',
                confirmarContraseña: '',
                rol: 'formacion'
            });

            if (onUsuarioCreado) await onUsuarioCreado();
            onClose();

        } catch (error) {
            console.error('❌ Error al crear usuario:', error);
            const mensaje = error.response?.data?.message || 'Error al crear usuario';
            mostrarNotificacion(mensaje, 'error');
        } finally {
            setEnviando(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[95vh] overflow-y-auto">
                {/* Header */}
                <div className="sticky top-0 bg-white p-6 border-b border-gray-200 rounded-t-2xl z-10">
                    <div className="flex items-center justify-between">
                        <h2 className="text-xl font-bold text-gray-800">
                            👥 Crear Nuevo Usuario
                        </h2>
                        <button
                            onClick={onClose}
                            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                        >
                            <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>
                </div>

                {/* Contenido */}
                <div className="p-6">
                    <form onSubmit={handleSubmit} className="space-y-5">
                        {/* Rol */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Rol en el Sistema *
                            </label>
                            <select
                                name="rol"
                                value={form.rol}
                                onChange={handleChange}
                                className="w-full px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-transparent transition-all duration-200"
                                required
                            >
                                <option value="formacion">🎓 Formación</option>
                                <option value="ti">💻 TI (Sistemas)</option>
                            </select>

                            <div className="mt-3 p-4 bg-gray-50 rounded-lg border border-gray-200">
                                {form.rol === 'formacion' && (
                                    <div className="text-sm text-gray-700">
                                        <strong>🎓 Formación:</strong> Puede registrar solicitudes de instalación de componentes de PC para sus asesores. Gestiona la información inicial de los equipos.
                                    </div>
                                )}
                                {form.rol === 'ti' && (
                                    <div className="text-sm text-gray-700">
                                        <strong>💻 TI (Sistemas):</strong> Revisa y valida las solicitudes de instalación. Realiza verificaciones técnicas y aprueba/rechaza instalaciones.
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* DNI */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                DNI *
                            </label>
                            <input
                                type="text"
                                name="dni"
                                value={form.dni}
                                onChange={handleChange}
                                maxLength="8"
                                pattern="\d{6,8}"
                                className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.dni ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                    }`}
                                placeholder="12345678"
                                required
                            />
                            {errores.dni && (
                                <p className="text-red-500 text-xs mt-1">{errores.dni}</p>
                            )}
                        </div>

                        {/* Nombre */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Nombre *
                            </label>
                            <input
                                type="text"
                                name="nombre"
                                value={form.nombre}
                                onChange={handleChange}
                                className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.nombre ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                    }`}
                                placeholder="Juan Carlos"
                                required
                            />
                            {errores.nombre && (
                                <p className="text-red-500 text-xs mt-1">{errores.nombre}</p>
                            )}
                        </div>

                        {/* Apellido */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Apellido *
                            </label>
                            <input
                                type="text"
                                name="apellido"
                                value={form.apellido}
                                onChange={handleChange}
                                className={`w-full px-3 py-3 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.apellido ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                    }`}
                                placeholder="Pérez López"
                                required
                            />
                            {errores.apellido && (
                                <p className="text-red-500 text-xs mt-1">{errores.apellido}</p>
                            )}
                        </div>

                        {/* Contraseña */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Contraseña *
                            </label>
                            <div className="relative">
                                <input
                                    type={mostrarContraseña ? 'text' : 'password'}
                                    name="contraseña"
                                    value={form.contraseña}
                                    onChange={handleChange}
                                    className={`w-full px-3 py-3 pr-10 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.contraseña ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                        }`}
                                    placeholder="••••••••"
                                    required
                                />
                                <button
                                    type="button"
                                    onClick={() => setMostrarContraseña(!mostrarContraseña)}
                                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                                >
                                    {mostrarContraseña ? '👁️' : '👁️‍🗨️'}
                                </button>
                            </div>
                            {errores.contraseña && (
                                <p className="text-red-500 text-xs mt-1">{errores.contraseña}</p>
                            )}
                        </div>

                        {/* Confirmar Contraseña */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Confirmar Contraseña *
                            </label>
                            <div className="relative">
                                <input
                                    type={mostrarConfirmar ? 'text' : 'password'}
                                    name="confirmarContraseña"
                                    value={form.confirmarContraseña}
                                    onChange={handleChange}
                                    className={`w-full px-3 py-3 pr-10 border rounded-lg focus:ring-2 focus:border-transparent transition-all duration-200 ${errores.confirmarContraseña ? 'border-red-500 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-200'
                                        }`}
                                    placeholder="••••••••"
                                    required
                                />
                                <button
                                    type="button"
                                    onClick={() => setMostrarConfirmar(!mostrarConfirmar)}
                                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                                >
                                    {mostrarConfirmar ? '👁️' : '👁️‍🗨️'}
                                </button>
                            </div>
                            {errores.confirmarContraseña && (
                                <p className="text-red-500 text-xs mt-1">{errores.confirmarContraseña}</p>
                            )}
                        </div>

                        {/* Estado del formulario */}
                        <div className="pt-4 border-t border-gray-200">
                            {formularioValido() ? (
                                <div className="flex items-center text-green-600 text-sm font-medium mb-4">
                                    <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                                    </svg>
                                    ✅ Listo para crear usuario
                                </div>
                            ) : (
                                <div className="flex items-center text-orange-600 text-sm font-medium mb-4">
                                    <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                                    </svg>
                                    ⚠️ Completa todos los campos requeridos
                                </div>
                            )}
                        </div>
                    </form>
                </div>

                {/* Footer */}
                <div className="sticky bottom-0 bg-white p-6 border-t border-gray-200 rounded-b-2xl">
                    <div className="flex flex-col sm:flex-row justify-end space-y-3 sm:space-y-0 sm:space-x-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="w-full sm:w-auto px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors font-medium"
                            disabled={enviando}
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            onClick={handleSubmit}
                            disabled={!formularioValido() || enviando}
                            className={`w-full sm:w-auto px-6 py-3 rounded-lg font-medium transition-all duration-200 flex items-center justify-center space-x-2 ${formularioValido() && !enviando
                                    ? 'bg-blue-600 text-white hover:bg-blue-700 hover:shadow-lg'
                                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                }`}
                        >
                            {enviando ? (
                                <>
                                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                                    <span>Creando...</span>
                                </>
                            ) : (
                                <>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                                    </svg>
                                    <span>Crear Usuario</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CrearUsuario;