import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, useNavigate, Navigate } from 'react-router-dom';
import axios from 'axios';
import setupAuthInterceptor from './utils/authInterceptor';

import LoginForm from './components/LoginForm';
import RegistroInicial from './components/RegistroInicial';
import PanelTI from './components/ti/PanelTI.jsx';
import PanelFormacion from './components/formacion/PanelFormacion';
import SolicitudesPublicas from './components/SolicitudesPublicas';
import ProtectedRoute from './ProtectedRoute';

// ✅ COMPONENTE WRAPPER PARA ACCEDER A navigate
const AppContent = () => {
  const [token, setToken] = useState(localStorage.getItem('token') || '');
  const [usuario, setUsuario] = useState(null);
  const [cargando, setCargando] = useState(true);
  const navigate = useNavigate();

  // ✅ CONFIGURAR INTERCEPTOR AL MONTAR EL COMPONENTE
  useEffect(() => {
    setupAuthInterceptor(navigate);
  }, [navigate]);

  // ✅ FUNCIÓN MEJORADA PARA VERIFICAR TOKEN
  useEffect(() => {
    const verificarToken = async () => {
      if (!token) {
        setCargando(false);
        return;
      }

      try {
        setCargando(true);
        
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Timeout')), 10000)
        );
        
        const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';
        const requestPromise = axios.get(`${API}/api/usuarios/perfil`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        const response = await Promise.race([requestPromise, timeoutPromise]);
        
        setUsuario(response.data.usuario); // <-- Cambia esto
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        
      } catch (error) {
        console.error('❌ Error al verificar token:', error);
        
        localStorage.removeItem('token');
        localStorage.removeItem('rol');
        setToken('');
        setUsuario(null);
        
        delete axios.defaults.headers.common['Authorization'];
        
        if (error.message === 'Timeout') {
          console.log('🕐 Timeout al verificar token - Sesión expirada');
        } else {
          console.log('🚨 Token inválido - Sesión expirada');
        }
        
      } finally {
        setCargando(false);
      }
    };

    verificarToken();
  }, [token]);

  // ✅ FUNCIÓN PARA CERRAR SESIÓN
  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('rol');
    setToken('');
    setUsuario(null);
    delete axios.defaults.headers.common['Authorization'];
    navigate('/');
  };

  // ✅ PANTALLA DE CARGA CON TIMEOUT VISUAL
  if (cargando) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-teal-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 text-lg font-medium">Verificando sesión...</p>
          <p className="text-gray-500 text-sm mt-2">Sistema TICHEK</p>
        </div>
      </div>
    );
  }

  // ✅ SI NO HAY TOKEN O USUARIO, VERIFICAR RUTA ACTUAL
  if (!token || !usuario) {
    const currentPath = window.location.pathname;
    
    // ✅ PERMITIR ACCESO A REGISTRO INICIAL Y SOLICITUDES PÚBLICAS SIN AUTENTICACIÓN
    if (currentPath === '/registro-inicial' || currentPath === '/solicitudes-publicas') {
        return (
            <Routes>
                <Route path="/registro-inicial" element={<RegistroInicial />} />
                <Route path="/solicitudes-publicas" element={<SolicitudesPublicas />} />
                <Route path="*" element={<LoginForm setToken={setToken} />} />
            </Routes>
        );
    }
    
    // ✅ PARA CUALQUIER OTRA RUTA, MOSTRAR LOGIN
    return <LoginForm setToken={setToken} />;
  }

  // ✅ VERIFICAR ROL AUTORIZADO (solo ti y formacion)
  if (!['ti', 'formacion'].includes(usuario.rol)) {
    return (
      <div className="min-h-screen bg-red-50 flex items-center justify-center">
        <div className="bg-white p-8 rounded-xl shadow-lg text-center max-w-md">
          <div className="text-red-500 text-6xl mb-4">🚫</div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">Acceso No Autorizado</h1>
          <p className="text-gray-600 mb-4">
            Tu rol "<span className="font-semibold text-red-600">{usuario.rol}</span>" no tiene acceso a este módulo.
          </p>
          <p className="text-sm text-gray-500 mb-6">
            Solo usuarios con rol "ti" o "formacion" pueden acceder.
          </p>
          <button
            onClick={handleLogout}
            className="bg-red-600 text-white px-6 py-2 rounded-lg hover:bg-red-700 transition-colors duration-200"
          >
            Cerrar Sesión
          </button>
        </div>
      </div>
    );
  }

  // ✅ RUTAS SIMPLIFICADAS SOLO PARA TI Y FORMACION
  return (
    <Routes>
        {/* ✅ RUTAS PÚBLICAS */}
        <Route path="/registro-inicial" element={<RegistroInicial />} />
        
        {/* ✅ RUTA PRINCIPAL - DASHBOARD SEGÚN ROL */}
        <Route path="/" element={<Navigate to="/dashboard" />} />
        
        <Route path="/dashboard" element={
            usuario.rol === 'ti' ? 
                <PanelTI usuario={usuario} token={token} onLogout={handleLogout} /> :
            usuario.rol === 'formacion' ? 
                <PanelFormacion usuario={usuario} token={token} onLogout={handleLogout} /> :
                <Navigate to="/" />
        } />

        {/* ✅ RUTAS DIRECTAS PROTEGIDAS */}
        <Route path="/panel-ti" element={
            <ProtectedRoute allowedRoles={['ti']}>
                <PanelTI usuario={usuario} token={token} onLogout={handleLogout} />
            </ProtectedRoute>
        } />
        
        <Route path="/panel-formacion" element={
            <ProtectedRoute allowedRoles={['formacion']}>
                <PanelFormacion usuario={usuario} token={token} onLogout={handleLogout} />
            </ProtectedRoute>
        } />
        
        {/* ✅ RUTA PÚBLICA PARA SOLICITUDES (sin autenticación) */}
        <Route path="/solicitudes-publicas" element={<SolicitudesPublicas />} />
        
        {/* ✅ CUALQUIER OTRA RUTA VA AL DASHBOARD */}
        <Route path="*" element={<Navigate to="/dashboard" />} />
    </Routes>
  );
};

// ✅ COMPONENTE PRINCIPAL
function App() {
  return (
    <Router>
      <AppContent />
    </Router>
  );
}

export default App;
