import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import GestionUsuarios from '../sistemas/usuarios/GestionUsuarios';
import GestionSolicitudes from '../ti/GestionSolicitudes';
import SolicitudesAprobadasRechazadas from '../ti/EstadisticasTI';
import RegistroEliminacion from '../ti/RegistroEliminacion';
import HistorialEliminaciones from '../ti/HistorialEliminaciones';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const PanelTI = ({ usuario, token, onLogout }) => {
    const [usuarios, setUsuarios] = useState([]);
    const [solicitudes, setSolicitudes] = useState([]);
    const [cargando, setCargando] = useState(true);
    const [modalCerrarSesion, setModalCerrarSesion] = useState(false);
    const [notificacion, setNotificacion] = useState(null);
    const [vistaActual, setVistaActual] = useState('usuarios');
    const navigate = useNavigate();

    // Cargar datos iniciales
    useEffect(() => {
        const cargarDatosIniciales = async () => {
            try {
                setCargando(true);
                
                // Cargar usuarios
                const usuariosRes = await axios.get(`${API}/api/sistemas/usuarios`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setUsuarios(usuariosRes.data.usuarios || usuariosRes.data);
                
                // Cargar solicitudes pendientes
                const solicitudesRes = await axios.get(`${API}/api/ti/solicitudes?estado=pendiente&limit=5`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setSolicitudes(solicitudesRes.data.solicitudes || []);
                
            } catch (error) {
                console.error('Error al cargar datos iniciales:', error);
                mostrarNotificacion('Error al cargar datos iniciales', 'error');
            } finally {
                setCargando(false);
            }
        };

        if (token) {
            cargarDatosIniciales();
        }
    }, [token]);

    // Recargar usuarios
    const recargarUsuarios = async () => {
        try {
            const response = await axios.get(`${API}/api/sistemas/usuarios`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setUsuarios(response.data.usuarios || response.data);
            mostrarNotificacion('Usuarios actualizados', 'success');
        } catch (error) {
            console.error('Error al recargar usuarios:', error);
            mostrarNotificacion('Error al actualizar usuarios', 'error');
        }
    };

    // Recargar solicitudes
    const recargarSolicitudes = async () => {
        try {
            const response = await axios.get(`${API}/api/ti/solicitudes`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setSolicitudes(response.data.solicitudes || []);
            mostrarNotificacion('Solicitudes actualizadas', 'success');
        } catch (error) {
            console.error('Error al recargar solicitudes:', error);
            mostrarNotificacion('Error al actualizar solicitudes', 'error');
        }
    };

    // Mostrar notificación
    const mostrarNotificacion = (mensaje, tipo = 'success') => {
        setNotificacion({ mensaje, tipo });
        setTimeout(() => setNotificacion(null), 5000);
    };

    // Cerrar sesión
    const confirmarCerrarSesion = () => {
        if (onLogout) {
            onLogout();
        }
        mostrarNotificacion('Sesión cerrada correctamente', 'info');
    };

    if (cargando) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-gray-600 text-lg font-medium">Cargando Panel de TI...</p>
                    <p className="text-gray-500 text-sm mt-2">Sistema de Instalaciones</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-50">
            {/* Header del TI */}
            <header className="bg-white shadow-lg border-b-4 border-blue-500">
                <div className="px-6 py-6">
                    <div className="flex justify-between items-center">
                        <div className="flex items-center space-x-4">
                            <div className="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center">
                                <svg className="w-7 h-7 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" />
                                </svg>
                            </div>
                            <div>
                                <h1 className="text-3xl font-bold text-blue-600">Panel de TI</h1>
                                <p className="text-gray-600 text-sm mt-1">
                                    Sistema de Gestión de Instalaciones
                                </p>
                            </div>
                        </div>

                        <div className="flex items-center space-x-4">
                            <div className="text-right">
                                <p className="text-sm font-medium text-gray-700">
                                    👋 {usuario.nombre} {usuario.apellido}
                                </p>
                                <p className="text-xs text-blue-600 font-medium">
                                    💻 TI (Sistemas)
                                </p>
                            </div>
                            <button
                                onClick={() => setModalCerrarSesion(true)}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all duration-200 flex items-center space-x-2"
                            >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                                </svg>
                                <span>Cerrar Sesión</span>
                            </button>
                        </div>
                    </div>
                </div>
            </header>

            {/* Navegación de pestañas */}
            <div className="mt-6 border-b border-gray-200">
                <nav className="-mb-px flex space-x-8">
                    <button
                        onClick={() => setVistaActual('usuarios')}
                        className={`py-2 px-1 border-b-2 font-medium text-sm ${
                            vistaActual === 'usuarios'
                                ? 'border-blue-500 text-blue-600'
                                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                    >
                        👥 Gestión de Usuarios
                    </button>
                    <button
                        onClick={() => setVistaActual('solicitudes')}
                        className={`py-2 px-1 border-b-2 font-medium text-sm ${
                            vistaActual === 'solicitudes'
                                ? 'border-blue-500 text-blue-600'
                                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                    >
                        🖥️ Gestión de Solicitudes
                    </button>
                    <button
                        onClick={() => setVistaActual('estadisticas')}
                        className={`py-2 px-1 border-b-2 font-medium text-sm ${
                            vistaActual === 'estadisticas'
                                ? 'border-blue-500 text-blue-600'
                                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                    >
                        📊 Historial General
                    </button>
                    <button
                        onClick={() => setVistaActual('eliminaciones')}
                        className={`py-2 px-1 border-b-2 font-medium text-sm ${
                            vistaActual === 'eliminaciones'
                                ? 'border-blue-500 text-blue-600'
                                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                    >
                        🗂️ Registro Eliminación
                    </button>
                    <button
                        onClick={() => setVistaActual('historial-eliminaciones')}
                        className={`py-2 px-1 border-b-2 font-medium text-sm ${
                            vistaActual === 'historial-eliminaciones'
                                ? 'border-blue-500 text-blue-600'
                                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                    >
                        📋 Historial Eliminaciones
                    </button>
                </nav>
            </div>

            {/* Contenido principal */}
            <main className="p-6 max-w-7xl mx-auto">
                {/* Contenido según vista actual */}
                {vistaActual === 'usuarios' && (
                    <GestionUsuarios
                        usuarios={usuarios}
                        token={token}
                        onUsuarioActualizado={recargarUsuarios}
                        mostrarNotificacion={mostrarNotificacion}
                    />
                )}
                {vistaActual === 'solicitudes' && (
                    <GestionSolicitudes
                        solicitudes={solicitudes}
                        token={token}
                        onSolicitudActualizada={recargarSolicitudes}
                        mostrarNotificacion={mostrarNotificacion}
                    />
                )}
                {vistaActual === 'estadisticas' && (
                    <SolicitudesAprobadasRechazadas token={token} />
                )}
                {vistaActual === 'eliminaciones' && (
                    <RegistroEliminacion 
                        token={token} 
                        mostrarNotificacion={mostrarNotificacion}
                        usuario={usuario}
                    />
                )}
                {vistaActual === 'historial-eliminaciones' && (
                    <HistorialEliminaciones 
                        token={token} 
                        mostrarNotificacion={mostrarNotificacion}
                    />
                )}
            </main>

            {/* Notificación */}
            {notificacion && (
                <div className="fixed top-4 right-4 z-50 max-w-sm w-full">
                    <div className={`flex items-start p-4 rounded-lg shadow-lg border ${
                        notificacion.tipo === 'success' 
                            ? 'bg-green-50 border-green-200 text-green-800'
                            : notificacion.tipo === 'error'
                            ? 'bg-red-50 border-red-200 text-red-800'
                            : 'bg-blue-50 border-blue-200 text-blue-800'
                    }`}>
                        <div className="ml-3 flex-1">
                            <p className="text-sm font-medium">{notificacion.mensaje}</p>
                        </div>
                        <button
                            onClick={() => setNotificacion(null)}
                            className="ml-4 text-gray-400 hover:text-gray-600"
                        >
                            ✕
                        </button>
                    </div>
                </div>
            )}

            {/* Modal Cerrar Sesión */}
            {modalCerrarSesion && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl w-full max-w-md max-h-[90vh] overflow-y-auto shadow-2xl">
                        {/* Header */}
                        <div className="p-4 sm:p-6 border-b border-gray-200">
                            <div className="flex items-center space-x-3">
                                <div className="w-10 h-10 sm:w-12 sm:h-12 bg-red-100 rounded-full flex items-center justify-center flex-shrink-0">
                                    <svg className="w-5 h-5 sm:w-6 sm:h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                                    </svg>
                                </div>
                                <div className="min-w-0 flex-1">
                                    <h3 className="text-lg sm:text-xl font-bold text-gray-900 leading-tight">
                                        ¿Cerrar Sesión?
                                    </h3>
                                    <p className="text-xs sm:text-sm text-gray-500 mt-1">
                                        Se cerrará tu sesión de TI
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Contenido */}
                        <div className="p-4 sm:p-6">
                            <p className="text-gray-600 text-sm sm:text-base leading-relaxed">
                                Se cerrará tu sesión actual y tendrás que volver a iniciar sesión para acceder al panel.
                            </p>
                        </div>

                        {/* Botones */}
                        <div className="p-4 sm:p-6 border-t border-gray-200">
                            <div className="flex flex-col sm:flex-row justify-end space-y-3 sm:space-y-0 sm:space-x-3">
                                <button
                                    onClick={() => setModalCerrarSesion(false)}
                                    className="w-full sm:w-auto px-4 py-2.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors text-sm font-medium"
                                >
                                    Cancelar
                                </button>
                                <button
                                    onClick={confirmarCerrarSesion}
                                    className="w-full sm:w-auto px-4 py-2.5 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm font-medium"
                                >
                                    Confirmar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default PanelTI;
