import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const SolicitudesPublicas = () => {
    const navigate = useNavigate();
    const [solicitudes, setSolicitudes] = useState([]);
    const [loading, setLoading] = useState(true);
    const [campanias, setCampanias] = useState([]);
    const [formadores, setFormadores] = useState([]);
    const [filtros, setFiltros] = useState({
        campanias: [],
        formadores: [],
        estado: ''
    });
    const [mostrarFiltros, setMostrarFiltros] = useState({
        campanias: false,
        formadores: false
    });

    useEffect(() => {
        cargarDatos();
    }, []);

    useEffect(() => {
        cargarSolicitudes();
    }, [filtros]);

    const cargarDatos = async () => {
        try {
            console.log('🔍 Cargando datos públicos...');
            
            // Cargar campañas disponibles
            console.log('📊 Cargando campañas...');
            const responseCampanias = await axios.get(`${API}/api/solicitudes-publicas/campanias`);
            console.log('✅ Respuesta campañas:', responseCampanias.data);
            setCampanias(responseCampanias.data.campanias || []);

            // Cargar formadores disponibles
            console.log('👥 Cargando formadores...');
            const responseFormadores = await axios.get(`${API}/api/solicitudes-publicas/formadores`);
            console.log('✅ Respuesta formadores:', responseFormadores.data);
            setFormadores(responseFormadores.data.formadores || []);

            // Cargar solicitudes iniciales
            cargarSolicitudes();
        } catch (error) {
            console.error('❌ Error al cargar datos:', error);
            if (error.response) {
                console.error('Response status:', error.response.status);
                console.error('Response data:', error.response.data);
            }
        }
    };

    const cargarSolicitudes = async () => {
        try {
            setLoading(true);
            console.log('📋 Cargando solicitudes públicas...');
            console.log('🔍 Filtros aplicados:', filtros);
            
            const params = new URLSearchParams();
            
            if (filtros.campanias.length > 0) {
                filtros.campanias.forEach(c => params.append('campanias', c));
            }
            if (filtros.formadores.length > 0) {
                filtros.formadores.forEach(f => params.append('formadores', f));
            }
            if (filtros.estado) {
                params.append('estado', filtros.estado);
            }

            console.log('🌐 URL params:', params.toString());
            const response = await axios.get(`${API}/api/solicitudes-publicas?${params}`);
            console.log('✅ Solicitudes obtenidas:', response.data.solicitudes?.length || 0);
            setSolicitudes(response.data.solicitudes || []);
        } catch (error) {
            console.error('❌ Error al cargar solicitudes:', error);
            if (error.response) {
                console.error('Response status:', error.response.status);
                console.error('Response data:', error.response.data);
            }
        } finally {
            setLoading(false);
        }
    };

    const toggleFiltro = (tipo, valor) => {
        setFiltros(prev => ({
            ...prev,
            [tipo]: prev[tipo].includes(valor)
                ? prev[tipo].filter(item => item !== valor)
                : [...prev[tipo], valor]
        }));
    };

    const limpiarFiltros = () => {
        setFiltros({
            campanias: [],
            formadores: [],
            estado: ''
        });
    };

    const formatearFecha = (fecha) => {
        if (!fecha) return '-';
        return new Date(fecha).toLocaleString('es-PE', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: false
        });
    };

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                {/* Header */}
                <div className="bg-white rounded-lg shadow-md p-6 mb-6">
                    <div className="flex justify-between items-center">
                        <div className="text-center flex-1">
                            <h1 className="text-3xl font-bold text-gray-900 mb-2">
                                📊 Vista General de Solicitudes
                            </h1>
                            <p className="text-gray-600">
                                Seguimiento público del estado de todas las solicitudes de instalación
                            </p>
                        </div>
                        <button
                            onClick={() => navigate('/')}
                            className="ml-4 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg transition-colors flex items-center space-x-2"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
                            </svg>
                            <span>Volver al Login</span>
                        </button>
                    </div>
                </div>

                {/* Filtros */}
                <div className="bg-white rounded-lg shadow-md p-6 mb-6">
                    <h2 className="text-lg font-semibold text-gray-800 mb-4">Filtros</h2>
                    
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                        {/* Filtro de Campañas */}
                        <div className="relative">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Campañas ({filtros.campanias.length} seleccionadas) - Total: {campanias.length}
                            </label>
                            <button
                                onClick={() => setMostrarFiltros(prev => ({...prev, campanias: !prev.campanias}))}
                                className="w-full px-4 py-2 text-left bg-white border border-gray-300 rounded-lg hover:bg-gray-50 flex justify-between items-center"
                            >
                                <span>
                                    {campanias.length === 0 ? 'Cargando campañas...' : 'Seleccionar campañas...'}
                                </span>
                                <svg className={`w-5 h-5 transition-transform ${mostrarFiltros.campanias ? 'rotate-180' : ''}`} 
                                     fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                                </svg>
                            </button>
                            
                            {mostrarFiltros.campanias && (
                                <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                                    {campanias.length === 0 ? (
                                        <div className="px-4 py-2 text-gray-500">
                                            {loading ? 'Cargando...' : 'No hay campañas disponibles'}
                                        </div>
                                    ) : (
                                        campanias.map((campania) => (
                                            <label key={campania} className="flex items-center px-4 py-2 hover:bg-gray-50 cursor-pointer">
                                                <input
                                                    type="checkbox"
                                                    checked={filtros.campanias.includes(campania)}
                                                    onChange={() => toggleFiltro('campanias', campania)}
                                                    className="mr-3 h-4 w-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                                                />
                                                <span className="text-sm text-gray-700">{campania}</span>
                                            </label>
                                        ))
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Filtro de Formadores */}
                        <div className="relative">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Formadores ({filtros.formadores.length} seleccionados) - Total: {formadores.length}
                            </label>
                            <button
                                onClick={() => setMostrarFiltros(prev => ({...prev, formadores: !prev.formadores}))}
                                className="w-full px-4 py-2 text-left bg-white border border-gray-300 rounded-lg hover:bg-gray-50 flex justify-between items-center"
                            >
                                <span>
                                    {formadores.length === 0 ? 'Cargando formadores...' : 'Seleccionar formadores...'}
                                </span>
                                <svg className={`w-5 h-5 transition-transform ${mostrarFiltros.formadores ? 'rotate-180' : ''}`} 
                                     fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                                </svg>
                            </button>
                            
                            {mostrarFiltros.formadores && (
                                <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                                    {formadores.length === 0 ? (
                                        <div className="px-4 py-2 text-gray-500">
                                            {loading ? 'Cargando...' : 'No hay formadores disponibles'}
                                        </div>
                                    ) : (
                                        formadores.map((formador) => (
                                            <label key={formador.id} className="flex items-center px-4 py-2 hover:bg-gray-50 cursor-pointer">
                                                <input
                                                    type="checkbox"
                                                    checked={filtros.formadores.includes(formador.nombre)}
                                                    onChange={() => toggleFiltro('formadores', formador.nombre)}
                                                    className="mr-3 h-4 w-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                                                />
                                                <span className="text-sm text-gray-700">{formador.nombre}</span>
                                            </label>
                                        ))
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Filtro de Estado */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Estado
                            </label>
                            <select
                                value={filtros.estado}
                                onChange={(e) => setFiltros(prev => ({...prev, estado: e.target.value}))}
                                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                            >
                                <option value="">Todos los estados</option>
                                <option value="pendiente">Pendiente</option>
                                <option value="aprobada">Aprobada</option>
                                <option value="rechazada">Rechazada</option>
                            </select>
                        </div>
                    </div>

                    <div className="flex justify-between items-center">
                        <div className="text-sm text-gray-600">
                            {filtros.campanias.length > 0 && (
                                <span className="mr-4">
                                    <strong>Campañas:</strong> {filtros.campanias.join(', ')}
                                </span>
                            )}
                            {filtros.formadores.length > 0 && (
                                <span>
                                    <strong>Formadores:</strong> {filtros.formadores.join(', ')}
                                </span>
                            )}
                        </div>
                        <button
                            onClick={limpiarFiltros}
                            className="px-4 py-2 text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                        >
                            Limpiar Filtros
                        </button>
                    </div>
                </div>

                {/* Tabla de Solicitudes */}
                <div className="bg-white rounded-lg shadow-md overflow-hidden">
                    <div className="px-6 py-4 border-b border-gray-200">
                        <h2 className="text-lg font-semibold text-gray-800">
                            Solicitudes ({solicitudes.length})
                        </h2>
                    </div>

                    {loading ? (
                        <div className="flex justify-center items-center py-12">
                            <div className="animate-spin rounded-full h-10 w-10 border-4 border-blue-500 border-t-transparent"></div>
                            <span className="ml-3 text-gray-600">Cargando solicitudes...</span>
                        </div>
                    ) : solicitudes.length === 0 ? (
                        <div className="text-center py-12">
                            <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                            <h3 className="mt-2 text-lg font-medium text-gray-900">No hay solicitudes</h3>
                            <p className="mt-1 text-sm text-gray-500">
                                No se encontraron solicitudes con los filtros aplicados
                            </p>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            DNI Asesor
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Nombre Asesor
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Campaña
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Formador
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Fecha Solicitud
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Estado
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Fecha Revisión
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {solicitudes.map((solicitud) => (
                                        <tr key={solicitud.id} className="hover:bg-gray-50">
                                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                                {solicitud.dni_asesor}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {solicitud.nombre_asesor}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {solicitud.campaña}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {solicitud.creador_nombre || '-'}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {formatearFecha(solicitud.fecha_creacion)}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                                                    solicitud.estado === 'aprobada'
                                                        ? 'bg-green-100 text-green-800'
                                                        : solicitud.estado === 'rechazada'
                                                            ? 'bg-red-100 text-red-800'
                                                            : 'bg-yellow-100 text-yellow-800'
                                                }`}>
                                                    {solicitud.estado === 'aprobada' ? 'Aprobada' :
                                                     solicitud.estado === 'rechazada' ? 'Rechazada' : 'Pendiente'}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {solicitud.estado !== 'pendiente' ? 
                                                    formatearFecha(solicitud.fecha_revision) : '-'}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="text-center mt-6 text-sm text-gray-500">
                    <p>Vista pública de solicitudes - Actualizada en tiempo real</p>
                </div>
            </div>
        </div>
    );
};

export default SolicitudesPublicas;
