import React, { useState, useMemo } from 'react';
import CrearUsuario from './CrearUsuario';
import EditarUsuario from './EditarUsuario';

const GestionUsuarios = ({ usuarios, token, onUsuarioActualizado, mostrarNotificacion }) => {
    const [filtros, setFiltros] = useState({
        busqueda: '',
        rol: '',
        estado: ''
    });
    
    const [paginaActual, setPaginaActual] = useState(1);
    const [modalCrear, setModalCrear] = useState(false);
    const [modalEditar, setModalEditar] = useState(false);
    const [usuarioEditar, setUsuarioEditar] = useState(null);
    
    const usuariosPorPagina = 10;

    // ✅ FILTRADO SIMPLIFICADO DE USUARIOS
    const usuariosFiltrados = useMemo(() => {
        return usuarios.filter(usuario => {
            const coincideBusqueda = !filtros.busqueda || 
                usuario.dni?.includes(filtros.busqueda) ||
                usuario.nombre?.toLowerCase().includes(filtros.busqueda.toLowerCase()) ||
                usuario.apellido?.toLowerCase().includes(filtros.busqueda.toLowerCase());

            const coincideRol = !filtros.rol || usuario.rol === filtros.rol;
            
            const coincideEstado = !filtros.estado || 
                (filtros.estado === 'activo' && usuario.activo) ||
                (filtros.estado === 'inactivo' && !usuario.activo);

            return coincideBusqueda && coincideRol && coincideEstado;
        });
    }, [usuarios, filtros]);

    // ✅ PAGINACIÓN
    const totalPaginas = Math.ceil(usuariosFiltrados.length / usuariosPorPagina);
    const usuariosPaginados = usuariosFiltrados.slice(
        (paginaActual - 1) * usuariosPorPagina,
        paginaActual * usuariosPorPagina
    );

    // ✅ FUNCIONES DE FILTRO
    const handleFiltroChange = (e) => {
        const { name, value } = e.target;
        setFiltros(prev => ({ ...prev, [name]: value }));
        setPaginaActual(1);
    };

    const limpiarFiltros = () => {
        setFiltros({
            busqueda: '',
            rol: '',
            estado: ''
        });
        setPaginaActual(1);
    };

    // ✅ FUNCIONES DE USUARIO
    const handleEditarClick = (usuario) => {
        setUsuarioEditar(usuario);
        setModalEditar(true);
    };

    // ✅ OBTENER ICONO Y COLOR POR ROL
    const obtenerDatosRol = (rol) => {
        if (rol === 'ti') {
            return {
                icono: '🖥️',
                nombre: 'TI',
                color: '#3b82f6',
                bgColor: 'rgba(59, 130, 246, 0.1)'
            };
        } else if (rol === 'formacion') {
            return {
                icono: '👥',
                nombre: 'Formación',
                color: '#10b981',
                bgColor: 'rgba(16, 185, 129, 0.1)'
            };
        } else {
            return {
                icono: '👤',
                nombre: 'Otro',
                color: '#6b7280',
                bgColor: 'rgba(107, 114, 128, 0.1)'
            };
        }
    };

    return (
        <div className="space-y-6">
            {/* ✅ PANEL DE FILTROS SIMPLIFICADO */}
            <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-semibold text-gray-800 flex items-center">
                        <svg className="w-6 h-6 mr-2 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                        </svg>
                        Filtros de Búsqueda
                    </h3>
                    <div className="flex space-x-3">
                        <button
                            onClick={limpiarFiltros}
                            className="px-4 py-2 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors duration-200 flex items-center space-x-2"
                        >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                            </svg>
                            <span>Limpiar</span>
                        </button>
                        <button
                            onClick={() => setModalCrear(true)}
                            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 hover:shadow-lg transition-all duration-200 flex items-center space-x-2"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                            </svg>
                            <span>Crear Usuario</span>
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {/* Búsqueda general */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Búsqueda
                        </label>
                        <div className="relative">
                            <svg className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                            </svg>
                            <input
                                type="text"
                                name="busqueda"
                                placeholder="DNI, nombre, apellido..."
                                value={filtros.busqueda}
                                onChange={handleFiltroChange}
                                className="pl-10 pr-4 py-2 w-full border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                            />
                        </div>
                    </div>

                    {/* Rol */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Rol del Usuario
                        </label>
                        <select
                            name="rol"
                            value={filtros.rol}
                            onChange={handleFiltroChange}
                            className="w-full py-2 px-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                        >
                            <option value="">Todos los roles</option>
                            <option value="ti">TI</option>
                            <option value="formacion">Formación</option>
                        </select>
                    </div>

                    {/* Estado */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Estado
                        </label>
                        <select
                            name="estado"
                            value={filtros.estado}
                            onChange={handleFiltroChange}
                            className="w-full py-2 px-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                        >
                            <option value="">Todos los estados</option>
                            <option value="activo">✅ Activos</option>
                            <option value="inactivo">❌ Inactivos</option>
                        </select>
                    </div>
                </div>

                <div className="mt-4 text-sm text-gray-600 flex justify-between items-center">
                    <span>
                        Mostrando <strong>{usuariosPaginados.length}</strong> de <strong>{usuariosFiltrados.length}</strong> usuarios
                    </span>
                    <span>
                        Total en sistema: <strong>{usuarios.length}</strong>
                    </span>
                </div>
            </div>

            {/* ✅ TABLA SIMPLIFICADA DE USUARIOS */}
            <div className="bg-white rounded-2xl shadow-lg overflow-hidden border border-gray-100">
                <div className="overflow-x-auto">
                    <table className="min-w-full">
                        <thead className="bg-gray-50 border-b border-gray-200">
                            <tr>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                    Usuario
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                    DNI
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                    Rol
                                </th>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                    Estado
                                </th>
                                <th className="px-6 py-4 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider">
                                    Acciones
                                </th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {usuariosPaginados.map((usuario) => {
                                const datosRol = obtenerDatosRol(usuario.rol);
                                
                                return (
                                    <tr key={usuario.id} className="hover:bg-gray-50 transition-colors duration-200">
                                        {/* Usuario */}
                                        <td className="px-6 py-4">
                                            <div className="flex items-center space-x-3">
                                                <div 
                                                    className="w-12 h-12 rounded-full flex items-center justify-center"
                                                    style={{ backgroundColor: datosRol.bgColor }}
                                                >
                                                    <span className="text-xl">{datosRol.icono}</span>
                                                </div>
                                                <div>
                                                    <div className="font-semibold text-gray-900">
                                                        {usuario.nombre} {usuario.apellido}
                                                    </div>
                                                    <div className="text-sm text-gray-500">ID: {usuario.id}</div>
                                                </div>
                                            </div>
                                        </td>

                                        {/* DNI */}
                                        <td className="px-6 py-4">
                                            <div className="font-mono text-sm bg-gray-100 px-2 py-1 rounded inline-block">
                                                {usuario.dni}
                                            </div>
                                        </td>

                                        {/* Rol */}
                                        <td className="px-6 py-4">
                                            <span 
                                                className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium"
                                                style={{
                                                    backgroundColor: datosRol.bgColor,
                                                    color: datosRol.color
                                                }}
                                            >
                                                {datosRol.icono} {datosRol.nombre}
                                            </span>
                                        </td>

                                        {/* Estado */}
                                        <td className="px-6 py-4">
                                            <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium transition-all duration-200 ${
                                                usuario.activo
                                                    ? 'bg-green-100 text-green-800 hover:bg-green-200'
                                                    : 'bg-red-100 text-red-800 hover:bg-red-200'
                                            }`}>
                                                <div className={`w-2 h-2 rounded-full mr-2 ${
                                                    usuario.activo ? 'bg-green-400' : 'bg-red-400'
                                                }`}></div>
                                                {usuario.activo ? 'Activo' : 'Inactivo'}
                                            </span>
                                        </td>

                                        {/* Acciones */}
                                        <td className="px-6 py-4">
                                            <div className="flex items-center justify-center">
                                                <button
                                                    onClick={() => handleEditarClick(usuario)}
                                                    className="p-2 rounded-lg bg-blue-100 text-blue-600 hover:bg-blue-200 hover:shadow-md transition-all duration-200"
                                                    title={`Editar ${usuario.nombre} ${usuario.apellido}`}
                                                >
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                                                    </svg>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {/* Estado vacío */}
                {usuariosPaginados.length === 0 && (
                    <div className="text-center py-12">
                        <svg className="w-16 h-16 mx-auto text-gray-300 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                        </svg>
                        <h3 className="text-lg font-medium text-gray-900 mb-2">No se encontraron usuarios</h3>
                        <p className="text-gray-500 mb-4">
                            {filtros.busqueda || filtros.rol || filtros.estado 
                                ? 'Intenta ajustar los filtros de búsqueda'
                                : 'Aún no hay usuarios registrados en el sistema'
                            }
                        </p>
                        <button
                            onClick={() => setModalCrear(true)}
                            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 hover:shadow-lg transition-all duration-200 flex items-center space-x-2 mx-auto"
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                            </svg>
                            <span>Crear Primer Usuario</span>
                        </button>
                    </div>
                )}
            </div>

            {/* ✅ PAGINACIÓN SIMPLIFICADA */}
            {totalPaginas > 1 && (
                <div className="bg-white rounded-lg shadow-sm p-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-2 text-sm text-gray-600">
                            <span>Página {paginaActual} de {totalPaginas}</span>
                            <span>•</span>
                            <span>{usuariosPaginados.length} de {usuariosFiltrados.length} usuarios</span>
                        </div>

                        <div className="flex items-center space-x-2">
                            <button
                                onClick={() => setPaginaActual(paginaActual - 1)}
                                disabled={paginaActual === 1}
                                className={`px-3 py-2 rounded-lg transition-all duration-200 flex items-center space-x-1 ${
                                    paginaActual === 1
                                        ? 'text-gray-400 cursor-not-allowed'
                                        : 'text-gray-600 hover:bg-gray-100'
                                }`}
                            >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
                                </svg>
                                <span>Anterior</span>
                            </button>

                            <div className="flex items-center space-x-1">
                                {Array.from({ length: Math.min(5, totalPaginas) }, (_, i) => {
                                    const numeroPagina = i + 1;
                                    return (
                                        <button
                                            key={numeroPagina}
                                            onClick={() => setPaginaActual(numeroPagina)}
                                            className={`px-3 py-2 rounded-lg transition-all duration-200 ${
                                                paginaActual === numeroPagina
                                                    ? 'bg-blue-600 text-white shadow-md'
                                                    : 'text-gray-600 hover:bg-gray-100'
                                            }`}
                                        >
                                            {numeroPagina}
                                        </button>
                                    );
                                })}
                            </div>

                            <button
                                onClick={() => setPaginaActual(paginaActual + 1)}
                                disabled={paginaActual === totalPaginas}
                                className={`px-3 py-2 rounded-lg transition-all duration-200 flex items-center space-x-1 ${
                                    paginaActual === totalPaginas
                                        ? 'text-gray-400 cursor-not-allowed'
                                        : 'text-gray-600 hover:bg-gray-100'
                                }`}
                            >
                                <span>Siguiente</span>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
                                </svg>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* ✅ MODALES */}
            {modalCrear && (
                <CrearUsuario
                    onClose={() => setModalCrear(false)}
                    onUsuarioCreado={onUsuarioActualizado}
                    mostrarNotificacion={mostrarNotificacion}
                />
            )}

            {modalEditar && usuarioEditar && (
                <EditarUsuario
                    usuario={usuarioEditar}
                    token={token}
                    onClose={() => {
                        setModalEditar(false);
                        setUsuarioEditar(null);
                    }}
                    onUsuarioActualizado={onUsuarioActualizado}
                    mostrarNotificacion={mostrarNotificacion}
                />
            )}
        </div>
    );
};

export default GestionUsuarios;