import axios from 'axios';

// ✅ CONFIGURAR INTERCEPTOR PARA DETECTAR TOKENS EXPIRADOS
const setupAuthInterceptor = (navigate) => {
    // Interceptor de respuesta
    axios.interceptors.response.use(
        (response) => {
            // Si la respuesta es exitosa, devolverla tal como está
            return response;
        },
        (error) => {
            // ✅ EXCLUIR MÚLTIPLES ENDPOINTS DEL INTERCEPTOR
            const esEndpointExcluido = error.config?.url?.includes('/api/auth/login') ||
                                     error.config?.url?.includes('/api/auth/verificar-registro-inicial') ||
                                     error.config?.url?.includes('/api/auth/registro-inicial') ||
                                     error.config?.url?.includes('/api/auth/existe');
            
            if (esEndpointExcluido) {
                // Para los endpoints excluidos, devolver el error sin interceptar
                return Promise.reject(error);
            }

            // ✅ DETECTAR ERRORES DE AUTENTICACIÓN SOLO PARA OTROS ENDPOINTS
            if (error.response?.status === 401 || error.response?.status === 403) {
                console.log('🚨 Token expirado o inválido - Cerrando sesión automáticamente');
                
                // Limpiar localStorage
                localStorage.removeItem('token');
                localStorage.removeItem('rol');
                
                if (navigate) {
                    // Redirigir al login si la función navigate está disponible
                    navigate('/login');
                }
            }
            
            // Rechazar la promesa para evitar que continúe
            return Promise.reject(error);
        }
    );
};

export default setupAuthInterceptor;