import React, { useState } from 'react';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const RegistroEliminacion = ({ token, mostrarNotificacion, usuario }) => {
    const [formData, setFormData] = useState({
        usuario_eliminado: '',
        equipo_hostname: '',
        metodo_aplicado: 'GUI + validación manual',
        observaciones: ''
    });
    const [loading, setLoading] = useState(false);
    const [errors, setErrors] = useState({});

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
        // Limpiar error del campo cuando el usuario empiece a escribir
        if (errors[name]) {
            setErrors(prev => ({
                ...prev,
                [name]: ''
            }));
        }
    };

    const validarFormulario = () => {
        const nuevosErrores = {};

        // Validar DNI (6-10 dígitos)
        if (!formData.usuario_eliminado) {
            nuevosErrores.usuario_eliminado = 'El DNI del usuario es obligatorio';
        } else if (!/^\d{6,10}$/.test(formData.usuario_eliminado)) {
            nuevosErrores.usuario_eliminado = 'El DNI debe tener entre 6 y 10 dígitos';
        }

        // Validar hostname
        if (!formData.equipo_hostname.trim()) {
            nuevosErrores.equipo_hostname = 'El hostname del equipo es obligatorio';
        } else if (formData.equipo_hostname.trim().length < 3) {
            nuevosErrores.equipo_hostname = 'El hostname debe tener al menos 3 caracteres';
        }

        // Validar método
        if (!formData.metodo_aplicado) {
            nuevosErrores.metodo_aplicado = 'El método aplicado es obligatorio';
        }

        setErrors(nuevosErrores);
        return Object.keys(nuevosErrores).length === 0;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!validarFormulario()) {
            return;
        }

        setLoading(true);

        try {
            const response = await axios.post(`${API}/api/ti/eliminaciones`, formData, {
                headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });

            if (response.data.success) {
                mostrarNotificacion('Eliminación registrada exitosamente', 'success');
                // Limpiar formulario
                setFormData({
                    usuario_eliminado: '',
                    equipo_hostname: '',
                    metodo_aplicado: 'GUI + validación manual',
                    observaciones: ''
                });
                setErrors({});
            }
        } catch (error) {
            console.error('Error al registrar eliminación:', error);
            if (error.response?.data?.message) {
                mostrarNotificacion(error.response.data.message, 'error');
            } else {
                mostrarNotificacion('Error al registrar la eliminación', 'error');
            }
        } finally {
            setLoading(false);
        }
    };

    const limpiarFormulario = () => {
        setFormData({
            usuario_eliminado: '',
            equipo_hostname: '',
            metodo_aplicado: 'GUI + validación manual',
            observaciones: ''
        });
        setErrors({});
    };

    return (
        <div className="bg-white rounded-lg shadow-md p-6">
            <div className="mb-6">
                <h2 className="text-2xl font-bold text-gray-800 mb-2">
                    🗑️ Registro de Eliminación de Usuario
                </h2>
                <p className="text-gray-600">
                    Registra la eliminación de un usuario del sistema por motivos de seguridad o administrativos.
                </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
                {/* DNI Usuario Eliminado */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        DNI del Usuario Eliminado *
                    </label>
                    <input
                        type="text"
                        name="usuario_eliminado"
                        value={formData.usuario_eliminado}
                        onChange={handleInputChange}
                        maxLength="10"
                        placeholder="Ej: 12345678"
                        className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${
                            errors.usuario_eliminado ? 'border-red-500' : 'border-gray-300'
                        }`}
                    />
                    {errors.usuario_eliminado && (
                        <p className="mt-1 text-sm text-red-600">{errors.usuario_eliminado}</p>
                    )}
                </div>

                {/* Hostname del Equipo */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Hostname del Equipo *
                    </label>
                    <input
                        type="text"
                        name="equipo_hostname"
                        value={formData.equipo_hostname}
                        onChange={handleInputChange}
                        placeholder="Ej: DESKTOP-ABC123"
                        className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${
                            errors.equipo_hostname ? 'border-red-500' : 'border-gray-300'
                        }`}
                    />
                    {errors.equipo_hostname && (
                        <p className="mt-1 text-sm text-red-600">{errors.equipo_hostname}</p>
                    )}
                </div>

                {/* Responsable (Solo lectura) */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Responsable
                    </label>
                    <input
                        type="text"
                        value={`${usuario.nombre} ${usuario.apellido} (${usuario.dni})`}
                        readOnly
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50 text-gray-600"
                    />
                </div>

                {/* Método Aplicado */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Método Aplicado *
                    </label>
                    <select
                        name="metodo_aplicado"
                        value={formData.metodo_aplicado}
                        onChange={handleInputChange}
                        className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${
                            errors.metodo_aplicado ? 'border-red-500' : 'border-gray-300'
                        }`}
                    >
                        <option value="GUI + validación manual">GUI + validación manual</option>
                        <option value="Comando PowerShell">Comando PowerShell</option>
                        <option value="Active Directory">Active Directory</option>
                        <option value="Eliminación física">Eliminación física</option>
                        <option value="Desactivación temporal">Desactivación temporal</option>
                    </select>
                    {errors.metodo_aplicado && (
                        <p className="mt-1 text-sm text-red-600">{errors.metodo_aplicado}</p>
                    )}
                </div>

                {/* Observaciones */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Observaciones
                    </label>
                    <textarea
                        name="observaciones"
                        value={formData.observaciones}
                        onChange={handleInputChange}
                        rows={4}
                        placeholder="Detalles adicionales sobre la eliminación..."
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                </div>

                {/* Botones */}
                <div className="flex justify-end space-x-4">
                    <button
                        type="button"
                        onClick={limpiarFormulario}
                        disabled={loading}
                        className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors disabled:opacity-50"
                    >
                        Limpiar
                    </button>
                    <button
                        type="submit"
                        disabled={loading}
                        className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors flex items-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {loading ? (
                            <>
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                                <span>Registrando...</span>
                            </>
                        ) : (
                            <>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                                </svg>
                                <span>Registrar Eliminación</span>
                            </>
                        )}
                    </button>
                </div>
            </form>
        </div>
    );
};

export default RegistroEliminacion;
