import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND || 'http://172.17.248.8:3001';

const RegistroInicial = () => {
  const [form, setForm] = useState({
    dni: '',
    nombre: '',
    apellido: '',
    contraseña: '',
    confirmarContraseña: ''
  });
  const [mensaje, setMensaje] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errores, setErrores] = useState({});
  const [mostrarContraseña, setMostrarContraseña] = useState(false);
  const [mostrarConfirmar, setMostrarConfirmar] = useState(false);
  const navigate = useNavigate();

  // Validaciones en tiempo real
  useEffect(() => {
    const validar = () => {
      const nuevosErrores = {};

      // DNI
      if (form.dni && !/^\d{8}$/.test(form.dni)) {
        nuevosErrores.dni = 'El DNI debe tener exactamente 8 dígitos';
      }

      // Nombre
      if (form.nombre && form.nombre.trim().length < 2) {
        nuevosErrores.nombre = 'El nombre debe tener al menos 2 caracteres';
      }

      // Apellido
      if (form.apellido && form.apellido.trim().length < 2) {
        nuevosErrores.apellido = 'El apellido debe tener al menos 2 caracteres';
      }

      // Contraseña
      if (form.contraseña && form.contraseña.length < 6) {
        nuevosErrores.contraseña = 'La contraseña debe tener al menos 6 caracteres';
      }

      // Confirmar contraseña
      if (form.contraseña !== form.confirmarContraseña) {
        nuevosErrores.confirmarContraseña = 'Las contraseñas no coinciden';
      }

      setErrores(nuevosErrores);
    };

    const timeout = setTimeout(validar, 300);
    return () => clearTimeout(timeout);
  }, [form]);

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === 'dni') {
      // Solo permitir números y limitar a 8 dígitos
      const soloNumeros = value.replace(/\D/g, '').slice(0, 8);
      setForm({ ...form, [name]: soloNumeros });
    } else if (name === 'nombre' || name === 'apellido') {
      // Convertir a mayúsculas
      setForm({ ...form, [name]: value.toUpperCase() });
    } else {
      setForm({ ...form, [name]: value });
    }
  };

  const formularioValido = () => {
    const camposObligatorios = ['dni', 'nombre', 'apellido', 'contraseña', 'confirmarContraseña'];
    const todosLlenos = camposObligatorios.every(campo => form[campo]?.trim());
    const sinErrores = Object.keys(errores).length === 0;

    return todosLlenos && sinErrores;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formularioValido()) {
      setMensaje('❌ Por favor, completa todos los campos correctamente');
      return;
    }

    setIsLoading(true);
    setMensaje('');

    try {
      const datosUsuario = {
        dni: form.dni.trim(),
        nombre: form.nombre.trim(),
        apellido: form.apellido.trim(),
        contraseña: form.contraseña,
        rol: 'ti' // El primer usuario será TI (administrador)
      };

      const response = await axios.post(`${API}/api/auth/registro-inicial`, datosUsuario);

      setMensaje('✅ Usuario administrador TI creado exitosamente. Redirigiendo al login...');

      // Limpiar formulario
      setForm({
        dni: '',
        nombre: '',
        apellido: '',
        contraseña: '',
        confirmarContraseña: ''
      });

      setTimeout(() => {
        navigate('/login');
      }, 2000);

    } catch (error) {
      console.error('Error al crear usuario inicial:', error);
      const mensajeError = error.response?.data?.message || 'No se pudo crear el usuario';
      setMensaje(`❌ Error: ${mensajeError}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-50 px-4">
      <div className="w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center shadow-lg">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-gray-800 mb-2">
            CONFIGURACIÓN INICIAL
          </h1>
          <p className="text-gray-600">Sistema de Instalaciones</p>
          <div className="mt-4 p-4 bg-blue-50 border border-blue-200 rounded-lg">
            <p className="text-sm text-blue-700">
              <span className="font-semibold">Importante:</span> Este usuario tendrá permisos de <strong>TI (Administrador)</strong> con acceso completo al sistema.
            </p>
          </div>
        </div>

        {/* Formulario */}
        <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
          <div className="mb-6">
            <h2 className="text-xl font-bold text-gray-800 text-center mb-2">
              Crear Usuario TI
            </h2>
            <p className="text-gray-500 text-center text-sm">
              Configura el primer usuario administrador del sistema
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* DNI */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                DNI *
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V8a2 2 0 00-2-2h-5m-4 0V4a2 2 0 114 0v2m-4 0a2 2 0 104 0m-4 0v2" />
                  </svg>
                </div>
                <input
                  type="text"
                  name="dni"
                  value={form.dni}
                  onChange={handleChange}
                  className={`w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 ${errores.dni ? 'border-red-500' : 'border-gray-300'
                    }`}
                  placeholder="12345678"
                  maxLength="8"
                  required
                />
              </div>
              {errores.dni && <p className="text-red-500 text-xs mt-1">{errores.dni}</p>}
            </div>

            {/* Nombre */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Nombre *
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                  </svg>
                </div>
                <input
                  type="text"
                  name="nombre"
                  value={form.nombre}
                  onChange={handleChange}
                  className={`w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 ${errores.nombre ? 'border-red-500' : 'border-gray-300'
                    }`}
                  placeholder="JUAN CARLOS"
                  required
                />
              </div>
              {errores.nombre && <p className="text-red-500 text-xs mt-1">{errores.nombre}</p>}
            </div>

            {/* Apellido */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Apellido *
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                  </svg>
                </div>
                <input
                  type="text"
                  name="apellido"
                  value={form.apellido}
                  onChange={handleChange}
                  className={`w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 ${errores.apellido ? 'border-red-500' : 'border-gray-300'
                    }`}
                  placeholder="PÉREZ LÓPEZ"
                  required
                />
              </div>
              {errores.apellido && <p className="text-red-500 text-xs mt-1">{errores.apellido}</p>}
            </div>

            {/* Contraseña */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Contraseña *
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                  </svg>
                </div>
                <input
                  type={mostrarContraseña ? "text" : "password"}
                  name="contraseña"
                  value={form.contraseña}
                  onChange={handleChange}
                  className={`w-full pl-10 pr-12 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 ${errores.contraseña ? 'border-red-500' : 'border-gray-300'
                    }`}
                  placeholder="Mínimo 6 caracteres"
                  required
                />
                <button
                  type="button"
                  onClick={() => setMostrarContraseña(!mostrarContraseña)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                >
                  {mostrarContraseña ? '👁️' : '👁️‍🗨️'}
                </button>
              </div>
              {errores.contraseña && <p className="text-red-500 text-xs mt-1">{errores.contraseña}</p>}
            </div>

            {/* Confirmar Contraseña */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Confirmar Contraseña *
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
                <input
                  type={mostrarConfirmar ? "text" : "password"}
                  name="confirmarContraseña"
                  value={form.confirmarContraseña}
                  onChange={handleChange}
                  className={`w-full pl-10 pr-12 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 ${errores.confirmarContraseña ? 'border-red-500' : 'border-gray-300'
                    }`}
                  placeholder="Repetir contraseña"
                  required
                />
                <button
                  type="button"
                  onClick={() => setMostrarConfirmar(!mostrarConfirmar)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
                >
                  {mostrarConfirmar ? '👁️' : '👁️‍🗨️'}
                </button>
              </div>
              {errores.confirmarContraseña && <p className="text-red-500 text-xs mt-1">{errores.confirmarContraseña}</p>}
            </div>

            {/* Estado del formulario */}
            <div className="flex items-center justify-between pt-4 border-t border-gray-200">
              <div>
                {formularioValido() ? (
                  <span className="text-green-600 text-sm font-medium flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                    </svg>
                    ✅ Listo para crear
                  </span>
                ) : (
                  <span className="text-orange-600 text-sm font-medium flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    ⚠️ Completa todos los campos
                  </span>
                )}
              </div>
            </div>

            {/* Mensaje */}
            {mensaje && (
              <div className={`p-4 rounded-lg ${mensaje.includes('✅') ? 'bg-green-50 border border-green-200 text-green-700' :
                  'bg-red-50 border border-red-200 text-red-700'
                }`}>
                <p className="text-sm font-medium">{mensaje}</p>
              </div>
            )}

            {/* Botones */}
            <div className="space-y-3">
              <button
                type="submit"
                disabled={isLoading || !formularioValido()}
                className={`w-full py-3 px-4 rounded-lg font-semibold transition-all duration-200 flex items-center justify-center space-x-2 shadow-lg hover:shadow-xl ${isLoading || !formularioValido()
                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                    : 'bg-blue-600 text-white hover:bg-blue-700'
                  }`}
              >
                {isLoading ? (
                  <>
                    <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    <span>Creando usuario...</span>
                  </>
                ) : (
                  <>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                    </svg>
                    <span>Crear Usuario TI</span>
                  </>
                )}
              </button>

              <button
                type="button"
                onClick={() => navigate('/login')}
                className="w-full py-2 px-4 text-gray-600 hover:text-gray-800 text-sm font-medium transition-colors duration-200"
              >
                ← Volver al Login
              </button>
            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="mt-6 text-center">
          <p className="text-xs text-gray-500">
            Sistema de Instalaciones · Configuración inicial
          </p>
        </div>
      </div>
    </div>
  );
};

export default RegistroInicial;