import React, { useState, useEffect } from 'react';

const Notificacion = ({ mensaje, tipo = 'success', duracion = 3000, onClose }) => {
    const [visible, setVisible] = useState(false);
    const [saliendo, setSaliendo] = useState(false);

    useEffect(() => {
        // Entrada con animación
        setTimeout(() => setVisible(true), 10);

        // Salida automática
        const timer = setTimeout(() => {
            setSaliendo(true);
            setTimeout(() => {
                onClose();
            }, 300);
        }, duracion);

        return () => clearTimeout(timer);
    }, [duracion, onClose]);

    const getIcono = () => {
        switch (tipo) {
            case 'success':
                return (
                    <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
                    </svg>
                );
            case 'error':
                return (
                    <svg className="w-6 h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                );
            case 'warning':
                return (
                    <svg className="w-6 h-6 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
                    </svg>
                );
            case 'info':
                return (
                    <svg className="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                );
            default:
                return null;
        }
    };

    const getColores = () => {
        switch (tipo) {
            case 'success':
                return 'bg-green-50 border-green-200 text-green-800';
            case 'error':
                return 'bg-red-50 border-red-200 text-red-800';
            case 'warning':
                return 'bg-yellow-50 border-yellow-200 text-yellow-800';
            case 'info':
                return 'bg-blue-50 border-blue-200 text-blue-800';
            default:
                return 'bg-gray-50 border-gray-200 text-gray-800';
        }
    };

    return (
        <div
            className={`
                fixed top-4 right-4 z-50 max-w-sm w-full
                transform transition-all duration-300 ease-in-out
                ${visible && !saliendo ? 'translate-x-0 opacity-100 scale-100' : 'translate-x-full opacity-0 scale-95'}
            `}
        >
            <div className={`
                flex items-start p-4 rounded-lg border shadow-lg backdrop-blur-sm
                ${getColores()}
            `}>
                <div className="flex-shrink-0">
                    {getIcono()}
                </div>
                <div className="ml-3 flex-1">
                    <p className="text-sm font-medium">
                        {mensaje}
                    </p>
                </div>
                <button
                    onClick={() => {
                        setSaliendo(true);
                        setTimeout(() => {
                            onClose();
                        }, 300);
                    }}
                    className="ml-4 inline-flex text-gray-400 hover:text-gray-600 transition-colors"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                </button>
            </div>
        </div>
    );
};

export default Notificacion;