import { useState } from 'react';

export const useNotificacion = () => {
    const [notificaciones, setNotificaciones] = useState([]);

    const mostrarNotificacion = (mensaje, tipo = 'success', duracion = 3000) => {
        const id = Date.now() + Math.random();
        const nuevaNotificacion = { id, mensaje, tipo, duracion };
        
        setNotificaciones(prev => [...prev, nuevaNotificacion]);

        // Auto-remover después de la duración especificada
        setTimeout(() => {
            cerrarNotificacion(id);
        }, duracion);
    };

    const cerrarNotificacion = (id) => {
        setNotificaciones(prev => prev.filter(n => n.id !== id));
    };

    return {
        notificaciones,
        mostrarNotificacion,
        cerrarNotificacion,
        // Métodos de conveniencia
        exito: (mensaje, duracion = 3000) => mostrarNotificacion(mensaje, 'success', duracion),
        error: (mensaje, duracion = 5000) => mostrarNotificacion(mensaje, 'error', duracion),
        advertencia: (mensaje, duracion = 3000) => mostrarNotificacion(mensaje, 'warning', duracion),
        info: (mensaje, duracion = 3000) => mostrarNotificacion(mensaje, 'info', duracion),
    };
};

export default useNotificacion;